import React from 'react';
import { Home, ShoppingBag, BarChart3, Utensils, User } from 'lucide-react';
import { Tab, NavItem } from '../types';

interface BottomNavProps {
  currentTab: Tab;
  onTabChange: (tab: Tab) => void;
}

const navItems: NavItem[] = [
  { id: Tab.HOME, label: 'Home', icon: Home },
  { id: Tab.MENU, label: 'Menu', icon: Utensils },
  { id: Tab.ORDERS, label: 'Orders', icon: ShoppingBag },
  { id: Tab.EARNINGS, label: 'Earnings', icon: BarChart3 },
  { id: Tab.PROFILE, label: 'Profile', icon: User },
];

export const BottomNav: React.FC<BottomNavProps> = ({ currentTab, onTabChange }) => {
  return (
    <div className="fixed bottom-0 left-0 right-0 z-50 bg-white border-t border-slate-100 px-6 pb-6 pt-3 h-[88px] md:hidden">
      <div className="flex justify-between items-center h-full w-full max-w-md mx-auto">
        {navItems.map((item) => {
          const isActive = currentTab === item.id;
          const Icon = item.icon;

          return (
            <button
              key={item.id}
              onClick={() => onTabChange(item.id)}
              className="flex flex-col items-center justify-center gap-1.5 w-14 pb-1 group relative"
            >
              <div className="relative">
                <Icon 
                  size={24} 
                  strokeWidth={isActive ? 2.5 : 2} 
                  style={{ color: isActive ? '#007FFF' : '#94A3B8' }}
                  className="transition-colors duration-300 group-hover:scale-110" 
                />

                {/* Notification Dot for Orders */}
                {item.id === Tab.ORDERS && !isActive && (
                  <span className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white"></span>
                )}
              </div>
              <span 
                style={{ color: isActive ? '#007FFF' : '#94A3B8' }}
                className="text-[10px] font-bold tracking-wide transition-colors duration-300 uppercase"
              >
                {item.label}
              </span>

              {/* Active Indicator Dot */}
              {isActive && (
                <div className="absolute -bottom-2 w-1 h-1 rounded-full bg-[#007FFF]" />
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Clock, 
  User, 
  Package, 
  ChevronRight,
  Utensils,
  Search,
  Mic,
  SlidersHorizontal
} from 'lucide-react';
import { OrderDetailView } from './OrderDetailView';
import { Order } from '../types';

interface OrdersViewProps {
  orders: Order[];
}

export const OrdersView: React.FC<OrdersViewProps> = ({ orders }) => {
  const [viewMode, setViewMode] = useState<'active' | 'bookings'>('active');
  const [activeOrderTab, setActiveOrderTab] = useState<'Delivery' | 'Takeaway' | 'Dine-in'>('Delivery');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  const filteredOrders = orders.filter(o => {
    const matchesTab = o.type === activeOrderTab;
    const matchesSearch = 
      o.id.toLowerCase().includes(searchQuery.toLowerCase()) || 
      o.customer.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesTab && matchesSearch;
  });

  if (selectedOrder) {
    return <OrderDetailView order={selectedOrder} onBack={() => setSelectedOrder(null)} />;
  }

  return (
    <div className="pb-32 px-6 pt-6 animate-in fade-in duration-500 bg-white font-sans">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight mb-6">Orders</h1>

      {/* Redesigned View Mode Toggle */}
      <div className="flex p-1 bg-slate-100/50 border border-slate-200/50 rounded-[20px] mb-6">
        <button
          className={`flex-1 py-2.5 rounded-[16px] text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${
            viewMode === 'active' 
            ? 'bg-white text-[#007FFF] shadow-[0_4px_12px_rgba(0,0,0,0.06)] border border-slate-200/50 scale-[1.02]' 
            : 'text-slate-400 hover:text-slate-600'
