      </div>

      {viewMode === 'active' ? (
        <>
           <div className="flex gap-3 mb-6">
              <div className="relative flex-1">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="text" 
                   placeholder="Search Order ID or Customer..." 
                   value={searchQuery}
                   onChange={(e) => setSearchQuery(e.target.value)}
                   className="w-full bg-slate-50 border border-slate-100 text-slate-700 py-3.5 pl-11 pr-10 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white focus:ring-1 focus:ring-blue-500/10 text-sm font-semibold transition-all"
                 />
                 <Mic className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-500 cursor-pointer" size={18} />
              </div>
              <button className="bg-white border border-slate-100 text-slate-400 w-14 h-14 rounded-2xl flex items-center justify-center hover:bg-slate-50 hover:text-slate-900 transition-all active:scale-95 shadow-sm">
                 <SlidersHorizontal size={18} />
              </button>
           </div>

           {/* Redesigned Order Type Toggle */}
           <div className="flex p-1 bg-slate-100/50 border border-slate-200/50 rounded-[20px] mb-6">
            {(['Delivery', 'Takeaway', 'Dine-in'] as const).map((tab) => {
                const isActive = activeOrderTab === tab;
                const count = orders.filter(o => o.type === tab).length;
                return (
                <button
                    key={tab}
                    onClick={() => setActiveOrderTab(tab)}
                    className={`flex-1 py-2.5 rounded-[16px] text-[10px] font-black uppercase tracking-widest transition-all duration-300 flex items-center justify-center gap-1.5 ${
                        isActive 
                        ? 'bg-white text-[#007FFF] shadow-[0_4px_12px_rgba(0,0,0,0.06)] border border-slate-200/50 scale-[1.02]' 
                        : 'text-slate-400 hover:text-slate-600'
                    }`}
                >
                    {tab}
                    {count > 0 && (
                        <span className={`px-1.5 py-0.5 rounded-full text-[9px] font-black ${isActive ? 'bg-blue-50 text-[#007FFF]' : 'bg-slate-200 text-slate-400'}`}>
                        {count}
                        </span>
                    )}
                </button>
                )
            })}
            </div>

            <div className="space-y-4">
                {filteredOrders.map((order) => {
                    const isUrgent = parseInt(order.time) < 15;
                    return (
                    <div 
                      key={order.id} 
                      onClick={() => setSelectedOrder(order)}
                      className="bg-white rounded-[32px] p-5 border border-slate-100 hover:border-blue-200 transition-all duration-300 active:scale-[0.98] cursor-pointer shadow-sm"
                    >
                        <div className="flex justify-between items-start mb-4">
