                                    <span className={`px-2 py-0.5 rounded-md text-[10px] font-black uppercase tracking-widest ${order.status === 'Ready' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'}`}>
                                        {order.status}
                                    </span>
                                    <span className="px-2 py-0.5 rounded-md text-[10px] font-black bg-white border border-slate-200 text-slate-400 uppercase tracking-widest">
                                        {order.type}
                                    </span>
                                </div>
                                <h4 className="text-xl font-black text-slate-900 tracking-tight"># {order.id}</h4>
                            </div>

                            <div className={`flex items-center gap-3 px-4 py-2.5 rounded-2xl border transition-all duration-300 ${
                                isUrgent 
                                ? 'bg-rose-50 border-rose-100' 
                                : 'bg-blue-50/50 border-blue-100/50'
                            }`}>
                                <div className={`w-9 h-9 flex items-center justify-center rounded-full ${
                                    isUrgent 
                                    ? 'bg-rose-500 text-white animate-pulse' 
                                    : 'bg-blue-500 text-white'
