                                    <Clock size={18} strokeWidth={2.5} />
                                </div>
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-wider leading-none mb-1">Time Left</span>
                                    <span className={`text-xl font-black font-mono leading-none tracking-tighter ${
                                        isUrgent ? 'text-rose-600' : 'text-blue-600'
                                    }`}>
                                        {order.time}
                                    </span>
                                </div>
                            </div>
                        </div>

                        <div className="bg-slate-50 rounded-2xl p-5 mb-5 border border-slate-100">
                            <div className="flex justify-between items-center mb-4 pb-4 border-b border-slate-200/60 border-dashed">
                                <div className="flex items-center gap-3">
                                    <div className="w-9 h-9 rounded-xl bg-white border border-slate-200 flex items-center justify-center text-slate-400">
                                        <User size={16} />
                                    </div>
                                    <div>
                                        <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest leading-none mb-1.5">Customer</p>
                                        <p className="text-sm font-bold text-slate-900 leading-none">{order.customer}</p>
