        <div className="flex flex-col items-center justify-center h-[50vh] text-slate-400 animate-in fade-in bg-white">
           <div className="bg-white border border-slate-200 p-8 rounded-[32px] shadow-sm mb-6">
             <Utensils size={40} className="text-slate-200" />
