import React, { useState, useRef, useEffect } from 'react';
import { 
  Clock, 
  User, 
  Package, 
  ChevronRight,
  Utensils,
  Search,
  Mic,
  SlidersHorizontal,
  Check,
  Filter
} from 'lucide-react';
import { OrderDetailView } from './OrderDetailView';
import { Order } from '../types';

interface OrdersViewProps {
  orders: Order[];
}

export const OrdersView: React.FC<OrdersViewProps> = ({ orders }) => {
  const [viewMode, setViewMode] = useState<'active' | 'bookings'>('active');
  const [activeOrderTab, setActiveOrderTab] = useState<'Delivery' | 'Takeaway' | 'Dine-in' | 'All'>('All');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [showFilters, setShowFilters] = useState(false);
  const filterRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterRef.current && !filterRef.current.contains(event.target as Node)) {
        setShowFilters(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const filteredOrders = orders.filter(o => {
    const matchesTab = activeOrderTab === 'All' || o.type === activeOrderTab;
    const matchesSearch = 
      o.id.toLowerCase().includes(searchQuery.toLowerCase()) || 
      o.customer.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesTab && matchesSearch;
  });

  if (selectedOrder) {
    return <OrderDetailView order={selectedOrder} onBack={() => setSelectedOrder(null)} />;
  }

  const orderTypes = ['All', 'Delivery', 'Takeaway', 'Dine-in'] as const;

  return (
    <div className="pb-32 px-6 pt-6 animate-in fade-in duration-500 bg-white font-sans">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight mb-6">Orders</h1>

      {/* Redesigned View Mode Toggle */}
      <div className="flex p-1 bg-slate-100/50 border border-slate-200/50 rounded-[20px] mb-6">
        <button
          className={`flex-1 py-2.5 rounded-[16px] text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${
            viewMode === 'active' 
            ? 'bg-white text-[#007FFF] shadow-[0_4px_12px_rgba(0,0,0,0.06)] border border-slate-200/50 scale-[1.02]' 
            : 'text-slate-400 hover:text-slate-600'
          }`}
          onClick={() => setViewMode('active')}
        >
          Active Orders
        </button>
        <button
          className={`flex-1 py-2.5 rounded-[16px] text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${
            viewMode === 'bookings' 
            ? 'bg-white text-[#007FFF] shadow-[0_4px_12px_rgba(0,0,0,0.06)] border border-slate-200/50 scale-[1.02]' 
            : 'text-slate-400 hover:text-slate-600'
          }`}
          onClick={() => setViewMode('bookings')}
        >
          Bookings
        </button>
      </div>

      {viewMode === 'active' ? (
        <>
           <div className="flex gap-3 mb-6 relative">
              <div className="relative flex-1">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="text" 
                   placeholder="Search Order ID or Customer..." 
                   value={searchQuery}
                   onChange={(e) => setSearchQuery(e.target.value)}
                   className="w-full bg-slate-50 border border-slate-100 text-slate-700 py-3.5 pl-11 pr-10 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white focus:ring-1 focus:ring-blue-500/10 text-sm font-semibold transition-all"
                 />
                 <Mic className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-500 cursor-pointer" size={18} />
              </div>

              <div className="relative" ref={filterRef}>
                <button 
                  onClick={() => setShowFilters(!showFilters)}
                  className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all active:scale-95 shadow-sm border ${
                    showFilters || activeOrderTab !== 'All' 
                    ? 'bg-slate-900 border-slate-900 text-white' 
                    : 'bg-white border-slate-100 text-slate-400 hover:bg-slate-50 hover:text-slate-900'
                  }`}
                >
                   <SlidersHorizontal size={18} />
                   {activeOrderTab !== 'All' && (
                     <span className="absolute -top-1 -right-1 w-4 h-4 bg-blue-500 rounded-full border-2 border-white text-[8px] flex items-center justify-center font-black">1</span>
                   )}
                </button>

                {/* Filter Dropdown */}
                {showFilters && (
                  <div className="absolute right-0 mt-3 w-56 bg-white border border-slate-100 rounded-[24px] shadow-[0_15px_40px_rgba(0,0,0,0.12)] z-[100] p-2 animate-in zoom-in-95 duration-200">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest p-3 pb-2">Filter by Type</p>
                    <div className="space-y-1">
                      {orderTypes.map((tab) => {
                        const isActive = activeOrderTab === tab;
                        const count = tab === 'All' ? orders.length : orders.filter(o => o.type === tab).length;
                        return (
                          <button
                            key={tab}
                            onClick={() => {
                              setActiveOrderTab(tab);
                              setShowFilters(false);
                            }}
                            className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
                              isActive ? 'bg-blue-50 text-blue-600' : 'text-slate-600 hover:bg-slate-50'
                            }`}
                          >
                            <div className="flex items-center gap-3">
                              <div className={`w-1.5 h-1.5 rounded-full ${isActive ? 'bg-blue-500' : 'bg-slate-200'}`}></div>
                              <span className="text-[13px] font-bold">{tab}</span>
                            </div>
                            <div className="flex items-center gap-2">
