import React, { useState, useRef, useEffect } from 'react';
import { 
  Clock, 
  User, 
  Package, 
  ChevronRight,
  Utensils,
  Search,
  Mic,
  SlidersHorizontal,
  Check,
  Filter,
  ShoppingBag,
  Globe,
  ChevronLast
} from 'lucide-react';
import { OrderDetailView } from './OrderDetailView';
import { Order } from '../types';

interface OrdersViewProps {
  orders: Order[];
}

export const OrdersView: React.FC<OrdersViewProps> = ({ orders }) => {
  const [viewMode, setViewMode] = useState<'active' | 'bookings'>('active');
  const [activeOrderTab, setActiveOrderTab] = useState<'Delivery' | 'Takeaway' | 'Dine-in' | 'All'>('All');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  // Tracking the step of each order: 0 (Start Prep), 1 (Mark Ready), 2 (Handover)
  const [orderSteps, setOrderSteps] = useState<Record<string, number>>({});
  const [completedOrders, setCompletedOrders] = useState<Set<string>>(new Set());

  const filterRef = useRef<HTMLDivElement>(null);
  const blueColor = '#007FFF';

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (filterRef.current && !filterRef.current.contains(event.target as Node)) {
        setShowFilters(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Initialize steps based on initial order status if not already set
  useEffect(() => {
    const newSteps = { ...orderSteps };
    let changed = false;
    orders.forEach(o => {
      if (orderSteps[o.id] === undefined) {
        if (o.status === 'Ready') newSteps[o.id] = 2;
        else if (o.status === 'Cooking' || o.status === 'Preparing') newSteps[o.id] = 1;
        else newSteps[o.id] = 0;
        changed = true;
      }
    });
    if (changed) setOrderSteps(newSteps);
  }, [orders]);

  const handleStatusUpdate = (e: React.MouseEvent, orderId: string) => {
    e.stopPropagation();
    const currentStep = orderSteps[orderId] || 0;

    if (currentStep < 2) {
      setOrderSteps(prev => ({
        ...prev,
        [orderId]: currentStep + 1
      }));
    } else {
      // Final step: Handover (Remove order)
      setCompletedOrders(prev => new Set(prev).add(orderId));
    }
  };

  const getButtonConfig = (orderId: string) => {
    const step = orderSteps[orderId] || 0;
    switch (step) {
      case 0: return { text: 'Start Preparation', color: blueColor };
      case 1: return { text: 'Mark as Ready', color: '#10B981' }; // Emerald
      case 2: return { text: 'Handover the Order', color: '#6366F1' }; // Indigo
      default: return { text: 'Mark as Ready', color: blueColor };
    }
  };

  const getDisplayStatus = (order: Order) => {
    const step = orderSteps[order.id];
    if (step === 1) return 'Preparing';
    if (step === 2) return 'Ready';
    return order.status;
  };

  const filteredOrders = orders.filter(o => {
    if (completedOrders.has(o.id)) return false;
    const matchesTab = activeOrderTab === 'All' || o.type === activeOrderTab;
    const matchesSearch = 
      o.id.toLowerCase().includes(searchQuery.toLowerCase()) || 
      o.customer.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesTab && matchesSearch;
  });

  if (selectedOrder) {
    return <OrderDetailView order={selectedOrder} onBack={() => setSelectedOrder(null)} />;
  }

  const orderTypes = ['All', 'Delivery', 'Takeaway', 'Dine-in'] as const;

  return (
    <div className="pb-32 px-6 pt-6 animate-in fade-in duration-500 bg-white font-sans">
      <h1 className="text-2xl font-bold text-slate-900 tracking-tight mb-6">Orders</h1>

      <div className="flex p-1 bg-slate-100/50 border border-slate-200/50 rounded-[20px] mb-6">
        <button
          className={`flex-1 py-2.5 rounded-[16px] text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${
            viewMode === 'active' 
            ? 'bg-white text-[#007FFF] shadow-[0_4px_12px_rgba(0,0,0,0.06)] border border-slate-200/50 scale-[1.02]' 
            : 'text-slate-400 hover:text-slate-600'
          }`}
          onClick={() => setViewMode('active')}
        >
          Active Orders
        </button>
        <button
          className={`flex-1 py-2.5 rounded-[16px] text-[10px] font-black uppercase tracking-widest transition-all duration-300 ${
            viewMode === 'bookings' 
            ? 'bg-white text-[#007FFF] shadow-[0_4px_12px_rgba(0,0,0,0.06)] border border-slate-200/50 scale-[1.02]' 
            : 'text-slate-400 hover:text-slate-600'
          }`}
          onClick={() => setViewMode('bookings')}
        >
          Bookings
        </button>
      </div>

      {viewMode === 'active' ? (
        <>
           <div className="flex gap-3 mb-6 relative">
              <div className="relative flex-1">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input 
                   type="text" 
                   placeholder="Search Order ID or Customer..." 
                   value={searchQuery}
                   onChange={(e) => setSearchQuery(e.target.value)}
                   className="w-full bg-slate-50 border border-slate-100 text-slate-700 py-3.5 pl-11 pr-10 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white focus:ring-1 focus:ring-blue-500/10 text-sm font-semibold transition-all"
                 />
                 <Mic className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-500 cursor-pointer" size={18} />
              </div>

              <div className="relative" ref={filterRef}>
                <button 
                  onClick={() => setShowFilters(!showFilters)}
                  className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all active:scale-95 shadow-sm border ${
                    showFilters || activeOrderTab !== 'All' 
                    ? 'bg-slate-900 border-slate-900 text-white' 
                    : 'bg-white border-slate-100 text-slate-400 hover:bg-slate-50 hover:text-slate-900'
                  }`}
                >
                   <SlidersHorizontal size={18} />
                   {activeOrderTab !== 'All' && (
                     <span className="absolute -top-1 -right-1 w-4 h-4 bg-blue-500 rounded-full border-2 border-white text-[8px] flex items-center justify-center font-black">1</span>
                   )}
                </button>

                {showFilters && (
                  <div className="absolute right-0 mt-3 w-56 bg-white border border-slate-100 rounded-[24px] shadow-[0_15px_40px_rgba(0,0,0,0.12)] z-[100] p-2 animate-in zoom-in-95 duration-200">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest p-3 pb-2">Filter by Type</p>
                    <div className="space-y-1">
                      {orderTypes.map((tab) => {
                        const isActive = activeOrderTab === tab;
                        const count = tab === 'All' ? orders.length : orders.filter(o => o.type === tab).length;
                        return (
                          <button
                            key={tab}
                            onClick={() => {
                              setActiveOrderTab(tab);
                              setShowFilters(false);
                            }}
                            className={`w-full flex items-center justify-between px-4 py-3 rounded-xl transition-all ${
                              isActive ? 'bg-blue-50 text-blue-600' : 'text-slate-600 hover:bg-slate-50'
                            }`}
                          >
                            <div className="flex items-center gap-3">
                              <div className={`w-1.5 h-1.5 rounded-full ${isActive ? 'bg-blue-500' : 'bg-slate-200'}`}></div>
                              <span className="text-[13px] font-bold">{tab}</span>
                            </div>
                            <div className="flex items-center gap-2">
                               <span className={`text-[10px] font-black px-2 py-0.5 rounded-lg ${isActive ? 'bg-blue-100/50' : 'bg-slate-100 text-slate-400'}`}>
                                 {count}
                               </span>
                               {isActive && <Check size={14} strokeWidth={3} />}
                            </div>
                          </button>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
           </div>

            <div className="space-y-4">
                {filteredOrders.length > 0 ? (
                  filteredOrders.map((order) => {
                      const btnConfig = getButtonConfig(order.id);
                      const displayStatus = getDisplayStatus(order);
                      const isReady = displayStatus === 'Ready';

                      return (
                      <div 
                        key={order.id} 
                        onClick={() => setSelectedOrder(order)}
                        className="bg-white rounded-[24px] p-4 border border-slate-100 hover:border-blue-200 transition-colors duration-300 active:scale-[0.98] cursor-pointer"
                      >
                        <div className="flex justify-between items-start mb-4">
                            <div>
                              <div className="flex items-center gap-2 mb-1.5">
                                  <span className={`px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wide ${
                                    isReady ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                                  }`}>
                                    {displayStatus}
                                  </span>
                                  <span className="px-2 py-0.5 rounded-md text-[10px] font-bold bg-white border border-slate-200 text-slate-600 uppercase tracking-wide">
                                    {order.type}
                                  </span>
                              </div>
                              <h4 className="text-xl font-black text-slate-800 tracking-tight">{order.id}</h4>
                            </div>

                            <div style={{ backgroundColor: 'rgba(0,127,255,0.03)', borderColor: 'rgba(0,127,255,0.1)' }} className="flex items-center gap-3 px-3 py-2 rounded-2xl border">
                              <div style={{ backgroundColor: blueColor }} className="w-8 h-8 flex items-center justify-center rounded-full text-white">
                                  <Clock size={16} strokeWidth={2.5} />
                              </div>
                              <div className="flex flex-col">
                                  <span className="text-[9px] font-bold text-slate-400 uppercase tracking-wider leading-none mb-0.5">Time Left</span>
                                  <span style={{ color: blueColor }} className="text-xl font-black font-mono leading-none tracking-tight">
                                    {order.time}
                                  </span>
                              </div>
                            </div>
                        </div>

                        <div className="bg-white rounded-2xl p-4 mb-4 border border-slate-200 space-y-3">
                            <div className="flex justify-between items-center pb-3 border-b border-slate-200/60 border-dashed">
                              <div className="flex items-center gap-3">
                                  <div className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500">
                                    <User size={14} />
                                  </div>
                                  <div>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase">Customer</p>
                                    <p className="text-sm font-bold text-slate-700">{order.customer}</p>
                                  </div>
                              </div>
                              <div className="text-right">
                                  <p className="text-[10px] text-slate-400 font-bold uppercase">Amount</p>
                                  <p className="text-sm font-bold text-slate-900">₹{order.total}</p>
                              </div>
                            </div>

                            <div className="flex justify-between items-center pb-3 border-b border-slate-200/60 border-dashed">
                              <div className="flex items-center gap-3">
                                  <div className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500">
                                    <Package size={14} />
                                  </div>
                                  <div>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase">Details</p>
                                    <p className="text-sm font-bold text-slate-700 truncate max-w-[140px]">{order.items}</p>
                                  </div>
                              </div>
                            </div>

                            <div className="flex justify-between items-center">
                              <div className="flex items-center gap-3">
                                  <div className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center text-slate-500">
                                    <Globe size={14} />
                                  </div>
                                  <div>
                                    <p className="text-[10px] font-bold text-slate-400 uppercase">Channel</p>
                                    <p className="text-sm font-bold text-slate-700">{order.channel}</p>
                                  </div>
                              </div>
                              <div className="w-8 h-8 flex items-center justify-center rounded-full bg-white border border-slate-200 text-slate-400">
                                  <ChevronRight size={16} />
                              </div>
                            </div>
                        </div>

                        <button 
                          onClick={(e) => handleStatusUpdate(e, order.id)}
                          style={{ backgroundColor: btnConfig.color }}
                          className="w-full hover:opacity-90 active:scale-[0.98] text-white font-bold py-3.5 rounded-xl text-sm transition-all flex items-center justify-center gap-2 shadow-sm"
                        >
