    if (newAddonName && newAddonPrice) {
      setAddons([...addons, { id: Date.now().toString(), name: newAddonName, price: newAddonPrice }]);
      setNewAddonName('');
      setNewAddonPrice('');
      setShowAddonForm(false);
    }
  };

  const removeAddon = (id: string) => {
    setAddons(addons.filter(a => a.id !== id));
