                              onChange={(e) => setBasePrice(e.target.value)}
                              className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl pl-11 pr-5 text-base font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all" 
