                            <div className="p-5 bg-blue-50 rounded-2xl border border-blue-100 space-y-4">
                               <div className="grid grid-cols-2 gap-3">
                                  <input type="text" placeholder="Name" value={newVariantName} onChange={(e) => setNewVariantName(e.target.value)} className="h-11 px-4 bg-white rounded-xl text-xs font-bold focus:outline-none" />
                                  <input type="number" placeholder="Price" value={newVariantPrice} onChange={(e) => setNewVariantPrice(e.target.value)} className="h-11 px-4 bg-white rounded-xl text-xs font-bold focus:outline-none" />
                               </div>
                               <div className="flex gap-2">
                                  <button onClick={() => setShowVariantForm(false)} className="flex-1 py-2 text-[9px] font-bold uppercase text-slate-400">Cancel</button>
                                  <button onClick={handleAddVariant} className="flex-1 bg-slate-900 text-white rounded-lg text-[9px] font-bold uppercase tracking-widest py-2">Add</button>
                               </div>
                            </div>
                          )}
                       </div>
                    )}
                 </div>
              </section>

              <section className="bg-white rounded-[40px] p-6 flex items-center justify-between border border-slate-100">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 rounded-[20px] bg-blue-50 flex items-center justify-center text-blue-500 border border-blue-100/50">
                       <Check size={28} strokeWidth={3} />
                    </div>
                    <div>
                       <h4 className="text-slate-900 font-black text-base tracking-tight leading-none uppercase">Active Status</h4>
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Visible on customer app</p>
                    </div>
                 </div>
                 <button onClick={() => setIsAvailable(!isAvailable)} className={`w-14 h-8 rounded-full p-1 transition-all duration-300 ${isAvailable ? 'bg-[#007FFF]' : 'bg-slate-200'}`}>
                    <div className={`w-6 h-6 bg-white rounded-full transition-transform duration-300 ${isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
                 </button>
              </section>

              <div className="flex items-start gap-4 px-2 py-4">
                 <Info size={16} className="text-slate-400 mt-0.5 shrink-0" />
                 <p className="text-[10px] font-medium text-slate-400 leading-relaxed uppercase tracking-wide">
                   Menu updates are reflected instantly. High resolution images increase conversion by 45%.
                 </p>
              </div>
            </div>
        </div>
    </div>
  );
};

