                    <div className="space-y-2">
                        <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Dietary Preference</label>
                        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 gap-1">
                            {DIETARY_OPTIONS.map(option => (
                              <button 
                                key={option.type} onClick={() => setDietaryType(option.type as any)}
                                className={`flex-1 py-3.5 rounded-xl text-[10px] font-black uppercase transition-all duration-300 flex items-center justify-center gap-2 ${
                                  dietaryType === option.type 
                                    ? `${option.activeColor} text-white shadow-md ring-1 ring-white/20` 
                                    : 'text-slate-400 hover:bg-slate-100/50'
                                }`}
                              >
                                <option.icon size={12} className={dietaryType === option.type ? 'text-white' : option.iconColor} strokeWidth={4} />
                                {option.label}
                              </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Description</label>
                        <textarea 
                          rows={3} placeholder="What makes this dish special?" value={description}
                          onChange={(e) => setDescription(e.target.value)}
                          className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-5 text-xs font-medium text-slate-600 focus:outline-none focus:bg-white focus:border-blue-500 transition-all resize-none"
                        />
                    </div>
                 </div>
              </section>

              <section className="space-y-4">
                 <div className="flex items-center gap-2">
                    <Award size={14} className="text-slate-400" />
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Item Highlighting</h3>
                 </div>
                 <div className="bg-white rounded-[32px] p-6 border border-slate-100 grid grid-cols-2 gap-3">
                    {ALL_BADGES.map((badge) => {
                      const isActive = selectedBadges.includes(badge.id);
                      const Icon = badge.icon;
                      return (
                        <button 
                          key={badge.id} onClick={() => toggleBadge(badge.id)}
                          className={`flex items-center gap-3 p-4 rounded-2xl border transition-all duration-300 ${
                            isActive ? 'border-blue-500 bg-blue-50 ring-1 ring-blue-500/10' : 'border-slate-100 bg-slate-50/50 hover:border-slate-200'
                          }`}
                        >
                           <div className={`w-9 h-9 rounded-xl flex items-center justify-center shrink-0 border ${isActive ? 'bg-white border-blue-100 shadow-sm' : 'bg-white border-slate-100'}`}>
                              <Icon size={18} className={isActive ? 'text-blue-500' : badge.color} />
                           </div>
                           <span className={`text-[11px] font-black uppercase tracking-tight text-left leading-none ${isActive ? 'text-blue-600' : 'text-slate-500'}`}>{badge.label}</span>
                        </button>
                      );
                    })}
                 </div>
              </section>

              <section className="space-y-4">
                 <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                       <IndianRupee size={14} className="text-slate-400" />
                       <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Pricing Strategy</h3>
                    </div>
                    <div className="flex items-center gap-3">
                       <span className="text-[9px] font-bold text-slate-400 uppercase">Has Variations?</span>
                       <button onClick={() => setHasVariations(!hasVariations)} className={`w-10 h-6 rounded-full p-1 transition-all ${hasVariations ? 'bg-blue-500' : 'bg-slate-200'}`}>
                          <div className={`w-4 h-4 bg-white rounded-full transition-transform ${hasVariations ? 'translate-x-4' : 'translate-x-0'}`} />
                       </button>
                    </div>
                 </div>

                 <div className="bg-white rounded-[32px] p-6 border border-slate-100 space-y-6">
                    {!hasVariations ? (
                       <div className="space-y-2 animate-in fade-in zoom-in-95 duration-300">
                          <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Base Price</label>
                          <div className="relative">
                            <span className="absolute left-5 top-1/2 -translate-y-1/2 font-bold text-slate-400 text-lg">₹</span>
                            <input 
                              type="number" placeholder="0.00" value={basePrice}
                              onChange={(e) => setBasePrice(e.target.value)}
                              className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl pl-11 pr-5 text-base font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all" 
                            />
                          </div>
                       </div>
                    ) : (
                       <div className="space-y-4 animate-in fade-in zoom-in-95 duration-300">
                          {variants.map(v => (
                            <div key={v.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                               <div className="flex items-center gap-4">
                                  <div className="w-9 h-9 rounded-xl bg-white border border-slate-100 flex items-center justify-center text-blue-500 font-bold">₹</div>
                                  <div>
                                     <p className="text-xs font-bold text-slate-900">{v.name}</p>
                                     <p className="text-[9px] font-bold text-slate-400 uppercase mt-1">₹ {v.price}</p>
                                  </div>
                               </div>
                               <button className="text-rose-400 p-2 hover:text-rose-600 transition-colors"><Trash2 size={16} /></button>
                            </div>
                          ))}
                          {!showVariantForm ? (
                            <button onClick={() => setShowVariantForm(true)} className="w-full h-14 border-2 border-dashed border-slate-100 rounded-2xl flex items-center justify-center gap-2 text-slate-400 hover:bg-slate-50 transition-all">
                               <PlusCircle size={16} />
                               <span className="text-[10px] font-bold uppercase tracking-widest">Add Variety</span>
                            </button>
                          ) : (
                            <div className="p-5 bg-blue-50 rounded-2xl border border-blue-100 space-y-4">
                               <div className="grid grid-cols-2 gap-3">
                                  <input type="text" placeholder="Name" value={newVariantName} onChange={(e) => setNewVariantName(e.target.value)} className="h-11 px-4 bg-white rounded-xl text-xs font-bold focus:outline-none" />
                                  <input type="number" placeholder="Price" value={newVariantPrice} onChange={(e) => setNewVariantPrice(e.target.value)} className="h-11 px-4 bg-white rounded-xl text-xs font-bold focus:outline-none" />
                               </div>
                               <div className="flex gap-2">
                                  <button onClick={() => setShowVariantForm(false)} className="flex-1 py-2 text-[9px] font-bold uppercase text-slate-400">Cancel</button>
                                  <button onClick={handleAddVariant} className="flex-1 bg-slate-900 text-white rounded-lg text-[9px] font-bold uppercase tracking-widest py-2">Add</button>
                               </div>
                            </div>
                          )}
                       </div>
                    )}
                 </div>
              </section>

              <section className="bg-white rounded-[40px] p-6 flex items-center justify-between border border-slate-100 shadow-sm">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 rounded-[20px] bg-blue-50 flex items-center justify-center text-blue-500 border border-blue-100/50">
                       <Check size={28} strokeWidth={3} />
                    </div>
                    <div>
                       <h4 className="text-slate-900 font-black text-base tracking-tight leading-none uppercase">Active Status</h4>
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Visible on customer app</p>
                    </div>
                 </div>
                 <button onClick={() => setIsAvailable(!isAvailable)} className={`w-14 h-8 rounded-full p-1 transition-all duration-300 ${isAvailable ? 'bg-[#007FFF]' : 'bg-slate-200'}`}>
                    <div className={`w-6 h-6 bg-white rounded-full transition-transform duration-300 shadow-sm ${isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
                 </button>
              </section>

              <div className="flex items-start gap-4 px-2 py-4">
                 <Info size={16} className="text-slate-400 mt-0.5 shrink-0" />
                 <p className="text-[10px] font-medium text-slate-400 leading-relaxed uppercase tracking-wide">
                   Menu updates are reflected instantly. High resolution images increase conversion by 45%.
                 </p>
              </div>
            </div>
        </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { 
  Search, 
  Mic, 
  Plus, 
  MoreVertical, 
  ChevronDown,
  SlidersHorizontal,
  ArrowLeft,
  Camera,
  Check,
  Sparkles,
  X,
  ImageIcon,
  Trash2,
  PlusCircle,
  Flame,
  Trophy,
  ThumbsUp,
  Star,
  ChevronRight,
  Info,
  Layers,
  IndianRupee,
  UtensilsCrossed,
  Layout,
  PlusSquare,
  Hash,
  Award,
  Zap,
  Droplets,
  Leaf,
  Heart,
  Pencil,
  AlertCircle,
  Circle,
  Egg as EggIcon
} from 'lucide-react';

interface MenuItem {
