  const [activeActionMenuId, setActiveActionMenuId] = useState<number | null>(null);
  const [itemToDelete, setItemToDelete] = useState<MenuItem | null>(null);

  const [categories, setCategories] = useState(['All', 'Pizza', 'Sides', 'Beverages', 'Combos']);
  const [isAddCategoryOpen, setIsAddCategoryOpen] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');

  const toggleAvailability = (id: number) => {
    setItems(items.map(item => 
      item.id === id ? { ...item, isAvailable: !item.isAvailable } : item
    ));
  };

  const handleDeleteItem = (id: number) => {
    setItems(items.filter(item => item.id !== id));
    setItemToDelete(null);
  };

  const handleSaveItem = (item: any) => {
    if (viewMode === 'edit' && editingItem) {
      setItems(items.map(i => i.id === editingItem.id ? { ...item, id: editingItem.id } : i));
    } else {
      setItems([...items, { ...item, id: Date.now() }]);
    }
    setViewMode('list');
    setEditingItem(null);
  };

  const handleAddCategory = () => {
    if (newCategoryName.trim() && !categories.includes(newCategoryName.trim())) {
      setCategories([...categories, newCategoryName.trim()]);
      setNewCategoryName('');
      setIsAddCategoryOpen(false);
    }
  };

  const filteredItems = items.filter(item => {
    const matchesCategory = activeCategory === 'All' || item.category === activeCategory;
    const matchesSearch = 
      item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
      (item.itemCode && item.itemCode.toLowerCase().includes(searchQuery.toLowerCase()));
    return matchesCategory && matchesSearch;
  });

  if (viewMode === 'create' || viewMode === 'edit') {
    return (
      <CreateItemView 
        onBack={() => {
          setViewMode('list');
          setEditingItem(null);
        }} 
        categories={categories.filter(c => c !== 'All')} 
        initialItem={editingItem}
        onSave={handleSaveItem}
      />
    );
  }

  return (
    <div className="pb-32 px-6 pt-6 animate-in fade-in duration-500 bg-white font-sans relative">

      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Menu</h1>
        <button 
          onClick={() => setViewMode('create')}
          style={{ backgroundColor: blueColor }}
          className="flex items-center gap-2 text-white px-5 py-3 rounded-2xl active:scale-95 transition-all"
        >
           <Plus size={20} strokeWidth={3} />
           <span className="text-xs font-black uppercase tracking-widest">Add Item</span>
        </button>
      </div>

      {/* Search & Filter */}
      <div className="flex gap-3 mb-8">
         <div className="relative flex-1">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search items by name or code..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 text-slate-700 py-4 pl-11 pr-10 rounded-2xl focus:outline-none focus:border-blue-500 focus:bg-white focus:ring-1 focus:ring-blue-500/10 text-sm font-bold transition-all"
            />
            {searchQuery && (
              <button 
                onClick={() => setSearchQuery('')}
                className="absolute right-12 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500"
              >
                <X size={16} />
              </button>
            )}
            <Mic className="absolute right-4 top-1/2 -translate-y-1/2 text-blue-500 cursor-pointer" size={18} />
         </div>
         <button className="bg-white border border-slate-100 text-slate-400 w-14 h-14 rounded-2xl flex items-center justify-center hover:bg-slate-50 hover:text-slate-900 transition-all active:scale-95">
            <SlidersHorizontal size={18} />
         </button>
      </div>

      {/* Categories */}
      <div className="flex gap-3 overflow-x-auto no-scrollbar mb-8 pb-2 -mx-6 px-6">
         {categories.map(cat => (
           <button 
             key={cat}
             onClick={() => setActiveCategory(cat)}
             className={`px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all duration-300 border flex-shrink-0 ${
               activeCategory === cat 
                 ? 'bg-slate-900 border-slate-900 text-white' 
                 : 'bg-white border-slate-100 text-slate-400 hover:border-blue-200'
             }`}
           >
             {cat}
           </button>
         ))}
         <button 
           onClick={() => setIsAddCategoryOpen(true)}
           className="px-6 py-2.5 rounded-full text-[11px] font-black uppercase tracking-widest transition-all duration-300 border border-dashed border-slate-200 text-slate-400 hover:border-blue-400 hover:text-blue-500 flex items-center gap-2 flex-shrink-0"
         >
           <Plus size={14} strokeWidth={3} /> Category
         </button>
      </div>

      {/* Items List */}
      <div className="space-y-6 mb-8">
        {filteredItems.length > 0 ? (
          filteredItems.map((item) => (
            <div key={item.id} className="bg-white rounded-[32px] overflow-hidden border border-slate-100 hover:border-blue-200 transition-all duration-300 group relative">
               <div className="relative h-56 w-full">
                  <img src={item.image} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                  <div className="absolute top-0 inset-x-0 p-5 flex justify-between items-start bg-gradient-to-b from-black/50 to-transparent">
                     <div className={`px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest backdrop-blur-md border border-white/20 ${item.isAvailable ? 'bg-blue-600/80 text-white' : 'bg-rose-500/80 text-white'}`}>
                        {item.isAvailable ? 'Live' : 'Hidden'}
                     </div>
                     <div className="relative">
                        <button 
                          onClick={() => setActiveActionMenuId(activeActionMenuId === item.id ? null : item.id)}
                          className="w-10 h-10 rounded-xl bg-white/20 backdrop-blur-md border border-white/20 flex items-center justify-center text-white hover:bg-white/40 transition-colors"
                        >
                           <MoreVertical size={18} />
                        </button>

                        {/* Action Menu Dropdown */}
                        {activeActionMenuId === item.id && (
                          <>
                            <div className="fixed inset-0 z-[100]" onClick={() => setActiveActionMenuId(null)} />
                            <div className="absolute right-0 mt-2 w-40 bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden z-[110] animate-in zoom-in-95 duration-200">
                               <button 
                                 onClick={() => {
                                   setEditingItem(item);
                                   setViewMode('edit');
                                   setActiveActionMenuId(null);
                                 }}
                                 className="w-full px-5 py-4 flex items-center gap-3 text-slate-700 hover:bg-slate-50 transition-colors text-xs font-bold uppercase tracking-wider"
                               >
                                  <Pencil size={14} className="text-blue-500" /> Edit
                               </button>
                               <button 
                                 onClick={() => {
                                   setItemToDelete(item);
                                   setActiveActionMenuId(null);
                                 }}
                                 className="w-full px-5 py-4 flex items-center gap-3 text-rose-500 hover:bg-rose-50 transition-colors text-xs font-bold uppercase tracking-wider border-t border-slate-50"
                               >
                                  <Trash2 size={14} /> Delete
                               </button>
                            </div>
                          </>
                        )}
                     </div>
                  </div>

                  {/* Image Overlay: Item Code */}
                  {item.itemCode && (
                    <div className="absolute bottom-5 left-5">
                      <div className="bg-white/90 backdrop-blur-md border border-white px-3 py-1.5 rounded-xl shadow-sm">
                        <div className="flex items-center gap-1.5">
                          <Hash size={10} className="text-blue-500" strokeWidth={3} />
                          <span className="text-xs font-black text-slate-900 tracking-tight">{item.itemCode}</span>
                        </div>
                      </div>
                    </div>
                  )}
               </div>

               <div className="p-6">
                  <div className="flex items-center justify-between mb-2">
                     <div className="flex items-center gap-3">
                        <h3 className="text-xl font-black text-slate-900 tracking-tight leading-none">{item.name}</h3>
                     </div>
                     <div className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase tracking-widest border ${item.isVeg ? 'bg-blue-50 text-blue-600 border-blue-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                        {item.dietaryType || (item.isVeg ? 'Veg' : 'Non-Veg')}
                     </div>
                  </div>

                  {/* Badges / Highlighters Display */}
                  {item.badges && item.badges.length > 0 && (
                    <div className="flex flex-wrap gap-2 mb-4">
                      {item.badges.map(badgeId => {
                        const badge = ALL_BADGES.find(b => b.id === badgeId);
                        if (!badge) return null;
                        const Icon = badge.icon;
                        return (
                          <div key={badgeId} className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg border ${badge.bg} ${badge.border} ${badge.color}`}>
                            <Icon size={10} strokeWidth={3} />
                            <span className="text-[9px] font-black uppercase tracking-wider">{badge.label}</span>
                          </div>
                        );
                      })}
                    </div>
                  )}

                  <p className="text-slate-500 text-xs font-semibold mt-2 mb-6 line-clamp-1">{item.description}</p>
                  <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                     <div className="flex flex-col">
                        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Price</span>
                        <span style={{ color: blueColor }} className="text-2xl font-black tracking-tighter leading-none">₹{item.price}</span>
                     </div>
                     <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.isAvailable ? 'Online' : 'Offline'}</span>
                        <button 
                          onClick={() => toggleAvailability(item.id)}
                          style={{ backgroundColor: item.isAvailable ? blueColor : '#E2E8F0' }}
                          className={`w-14 h-8 rounded-full p-1 transition-all duration-500 relative`}
                        >
                           <div className={`w-6 h-6 bg-white rounded-full transform transition-transform duration-500 ${item.isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
                        </button>
                     </div>
                  </div>
               </div>
            </div>
          ))
        ) : (
          <div className="py-20 text-center bg-slate-50 rounded-[40px] border border-dashed border-slate-200">
             <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 text-slate-300 shadow-sm">
                <Search size={24} />
             </div>
             <p className="text-[11px] font-black text-slate-500 uppercase tracking-widest">No matching items</p>
             <p className="text-[10px] font-medium text-slate-400 mt-2">Try searching by a different name or code</p>
             {searchQuery && (
               <button 
                onClick={() => setSearchQuery('')}
                className="mt-6 text-xs font-black text-blue-500 uppercase tracking-widest"
               >
                 Clear Search
               </button>
             )}
          </div>
        )}
      </div>

      {/* Delete Confirmation Modal */}
      {itemToDelete && (
        <div className="fixed inset-0 z-[600] bg-slate-900/40 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="bg-white rounded-[40px] w-full max-w-sm p-10 text-center animate-in zoom-in duration-500 relative border border-slate-100 shadow-2xl">
              <div className="w-20 h-20 bg-rose-50 rounded-[28px] flex items-center justify-center mx-auto mb-8 border border-rose-100">
                 <AlertCircle size={40} className="text-rose-500" strokeWidth={2.5} />
              </div>

              <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-3 uppercase">Delete Item?</h3>
              <p className="text-[11px] font-medium text-slate-400 mb-10 leading-relaxed px-4 uppercase tracking-widest">
                Are you sure you want to remove <span className="text-slate-900 font-black">"{itemToDelete.name}"</span>? This action cannot be undone.
              </p>

              <div className="space-y-3">
                 <button 
                   onClick={() => handleDeleteItem(itemToDelete.id)}
                   className="w-full h-14 bg-rose-500 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest active:scale-95 transition-all shadow-lg shadow-rose-200"
                 >
                    Delete Permanently
                 </button>
                 <button 
                   onClick={() => setItemToDelete(null)}
                   className="w-full h-14 bg-slate-50 text-slate-400 rounded-2xl font-black text-[11px] uppercase tracking-widest active:scale-95 transition-all"
                 >
                    Nevermind
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Add Category Modal */}
      {isAddCategoryOpen && (
        <div className="fixed inset-0 z-[600] bg-slate-900/40 backdrop-blur-sm flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white rounded-[32px] w-full max-w-sm p-8 space-y-6 relative border border-slate-100 animate-in zoom-in-95 duration-300">
            <button 
              onClick={() => setIsAddCategoryOpen(false)}
              className="absolute top-6 right-6 p-2 text-slate-300 hover:text-slate-900"
            >
              <X size={20} />
            </button>

            <div className="text-center space-y-2">
              <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Add Category</h3>
              <p className="text-[10px] font-semibold text-slate-400 uppercase tracking-widest">Organize your menu items</p>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Category Name</label>
                <input 
                  type="text"
                  placeholder="e.g. Desserts, Platters"
                  value={newCategoryName}
                  onChange={(e) => setNewCategoryName(e.target.value)}
                  autoFocus
                  className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
                />
              </div>
              <button 
                onClick={handleAddCategory}
                disabled={!newCategoryName.trim()}
                style={{ backgroundColor: blueColor }}
                className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all shadow-lg shadow-blue-500/20"
              >
                Create Category
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const CreateItemView: React.FC<{ 
  onBack: () => void, 
  categories: string[],
  initialItem?: MenuItem | null,
  onSave: (item: any) => void
}> = ({ onBack, categories, initialItem, onSave }) => {
  const [dietaryType, setDietaryType] = useState<'Veg' | 'Non-Veg' | 'Egg'>(initialItem?.dietaryType || 'Veg');
  const [isAvailable, setIsAvailable] = useState(initialItem?.isAvailable ?? true);
  const [category, setCategory] = useState(initialItem?.category || categories[0] || 'Pizza');
  const [name, setName] = useState(initialItem?.name || '');
  const [itemCode, setItemCode] = useState(initialItem?.itemCode || '');
  const [description, setDescription] = useState(initialItem?.description || '');
  const [basePrice, setBasePrice] = useState(initialItem?.price?.toString() || '');
  const [selectedBadges, setSelectedBadges] = useState<string[]>(initialItem?.badges || []);

  const [hasVariations, setHasVariations] = useState(false);
  const [variants, setVariants] = useState<any[]>([]);
  const [showVariantForm, setShowVariantForm] = useState(false);
  const [newVariantName, setNewVariantName] = useState('');
  const [newVariantPrice, setNewVariantPrice] = useState('');

  const handleSave = () => {
    onSave({
      name,
      itemCode,
      category,
      description,
      price: parseFloat(basePrice) || 0,
      isVeg: dietaryType === 'Veg',
      isAvailable,
      dietaryType,
      badges: selectedBadges,
      image: initialItem?.image || 'https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=400&auto=format&fit=crop'
    });
  };

  const toggleBadge = (id: string) => {
    setSelectedBadges(prev => prev.includes(id) ? prev.filter(b => b !== id) : [...prev, id]);
  };

  const handleAddVariant = () => {
    if (newVariantName && newVariantPrice) {
      setVariants([...variants, { id: Date.now().toString(), name: newVariantName, price: newVariantPrice }]);
      setNewVariantName(''); setNewVariantPrice(''); setShowVariantForm(false);
    }
  };

  const DIETARY_OPTIONS = [
    { type: 'Veg', label: 'Veg', icon: Circle, activeColor: 'bg-green-600', textColor: 'text-green-600', borderColor: 'border-green-100', iconColor: 'text-green-600' },
    { type: 'Non-Veg', label: 'Non-Veg', icon: Circle, activeColor: 'bg-rose-600', textColor: 'text-rose-600', borderColor: 'border-rose-100', iconColor: 'text-rose-600' },
    { type: 'Egg', label: 'Egg', icon: EggIcon, activeColor: 'bg-amber-500', textColor: 'text-amber-600', borderColor: 'border-amber-100', iconColor: 'text-amber-500' }
  ];

  return (
    <div className="fixed inset-0 z-[500] bg-white flex flex-col animate-in slide-in-from-bottom duration-500 font-sans">
        <div className="px-6 py-6 flex items-center justify-between bg-white border-b border-slate-100 sticky top-0 z-50">
            <div className="flex items-center gap-4">
              <button onClick={onBack} className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 active:scale-90 transition-all border border-slate-100">
                <ArrowLeft size={20} />
              </button>
              <div>
                <h2 className="text-lg font-bold text-slate-900 tracking-tight leading-none uppercase">{initialItem ? 'Edit Item' : 'Create Item'}</h2>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1.5">v3.2 Stable</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
               <button onClick={onBack} className="px-5 py-2.5 rounded-xl text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:bg-slate-50 transition-all">
                 Cancel
               </button>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar">
            <div className="bg-white p-6 border-b border-slate-100 mb-6">
               <div className="aspect-video w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-[32px] flex flex-col items-center justify-center relative overflow-hidden group cursor-pointer">
                  {initialItem?.image ? (
                    <img src={initialItem.image} className="absolute inset-0 w-full h-full object-cover" alt="Preview" />
                  ) : (
                    <>
                      <div className="w-14 h-14 rounded-[20px] bg-white border border-slate-100 flex items-center justify-center text-slate-300">
                        <Camera size={28} />
                      </div>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-4">Upload Banner Photo</span>
                    </>
                  )}
                  <div className="absolute bottom-4 right-4 bg-white/80 backdrop-blur-md px-3 py-1.5 rounded-xl border border-slate-100 flex items-center gap-2">
                    <Sparkles size={12} className="text-blue-500" fill="currentColor" />
                    <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">AI Enhanced</span>
                  </div>
               </div>
            </div>

            <div className="px-6 space-y-8 pb-32">
              <section className="space-y-4">
                 <div className="flex items-center gap-2">
                    <UtensilsCrossed size={14} className="text-slate-400" />
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Product Details</h3>
                 </div>

                 <div className="bg-white rounded-[32px] p-6 border border-slate-100 space-y-6">
                    <div className="grid grid-cols-4 gap-4">
                        <div className="space-y-2 col-span-1">
                            <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Code</label>
                            <input 
                              type="text" placeholder="01" value={itemCode}
                              onChange={(e) => setItemCode(e.target.value)}
                              className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-4 text-sm font-bold text-slate-900 text-center focus:outline-none focus:bg-white focus:border-blue-500 transition-all" 
                            />
                        </div>
                        <div className="space-y-2 col-span-3">
                            <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Item Title</label>
                            <input 
                              type="text" placeholder="e.g. Classic Margherita" value={name}
                              onChange={(e) => setName(e.target.value)}
                              className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all" 
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Category</label>
                        <div className="relative">
                          <select 
                            value={category} onChange={(e) => setCategory(e.target.value)}
                            className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-xs font-bold text-slate-900 focus:outline-none appearance-none"
                          >
                            {categories.map(cat => <option key={cat} value={cat}>{cat}</option>)}
                          </select>
                          <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Dietary Preference</label>
                        <div className="flex bg-slate-50 p-1 rounded-2xl border border-slate-100 gap-1">
                            {DIETARY_OPTIONS.map(option => (
                              <button 
                                key={option.type} onClick={() => setDietaryType(option.type as any)}
                                className={`flex-1 py-3.5 rounded-xl text-[10px] font-black uppercase transition-all duration-300 flex items-center justify-center gap-2 ${
                                  dietaryType === option.type 
                                    ? `${option.activeColor} text-white shadow-md ring-1 ring-white/20` 
                                    : 'text-slate-400 hover:bg-slate-100/50'
                                }`}
                              >
                                <option.icon size={12} className={dietaryType === option.type ? 'text-white' : option.iconColor} strokeWidth={4} />
                                {option.label}
                              </button>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-[9px] font-bold text-slate-400 uppercase tracking-widest ml-1">Description</label>
                        <textarea 
                          rows={3} placeholder="What makes this dish special?" value={description}
                          onChange={(e) => setDescription(e.target.value)}
                          className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-5 text-xs font-medium text-slate-600 focus:outline-none focus:bg-white focus:border-blue-500 transition-all resize-none"
                        />
                    </div>
                 </div>
              </section>

              <section className="space-y-4">
                 <div className="flex items-center gap-2">
                    <Award size={14} className="text-slate-400" />
                    <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Item Highlighting</h3>
                 </div>
                 <div className="bg-white rounded-[32px] p-6 border border-slate-100 grid grid-cols-2 gap-3">
                    {ALL_BADGES.map((badge) => {
                      const isActive = selectedBadges.includes(badge.id);
                      const Icon = badge.icon;
                      return (
                        <button 
                          key={badge.id} onClick={() => toggleBadge(badge.id)}
                          className={`flex items-center gap-3 p-4 rounded-2xl border transition-all duration-300 ${
                            isActive ? 'border-blue-500 bg-blue-50 ring-1 ring-blue-500/10' : 'border-slate-100 bg-slate-50/50 hover:border-slate-200'
                          }`}
