             className="w-full max-w-md bg-white rounded-t-[40px] p-8 shadow-[0_-20px_50px_rgba(0,0,0,0.1)] border-t border-slate-100 animate-in slide-in-from-bottom duration-500 ease-out flex flex-col max-h-[90vh]"
           >
              {/* Modal Header */}
              <div className="flex items-center justify-between mb-8 shrink-0">
                 <div className="w-10"></div>
                 <div className="text-center flex-1">
                    <h2 className="text-2xl font-black text-[#0F172A] tracking-tight uppercase">Manage Types</h2>
                    <p className="text-xs font-medium text-slate-400 leading-snug mt-1.5 px-4">
                       Add, edit or remove table categories.
                    </p>
                 </div>
                 <button 
                   onClick={() => {
                     setIsManageTypesOpen(false);
                     setEditingTypeIndex(null);
                     setNewTypeName('');
                   }}
                   className="w-10 h-10 flex items-center justify-center text-slate-300 hover:text-slate-900 transition-colors"
                 >
                    <X size={24} />
                 </button>
              </div>

              {/* Input Section */}
              <div className="space-y-6 mb-8 shrink-0">
                 <div className="space-y-2">
                    <label className="text-sm font-bold text-[#0F172A]">{editingTypeIndex !== null ? 'Update Type Name' : 'New Type Name'}</label>
                    <div className="flex gap-2">
                       <input 
                         type="text" 
                         value={newTypeName}
                         onChange={(e) => setNewTypeName(e.target.value)}
                         placeholder="e.g., Lounge, Rooftop"
                         className="flex-1 h-14 bg-white border border-slate-100 rounded-2xl px-5 text-slate-600 font-medium focus:outline-none focus:border-[#007FFF]/40"
                       />
                       <button 
                         onClick={handleAddOrUpdateType}
                         disabled={!newTypeName.trim()}
                         className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white transition-all active:scale-90 ${newTypeName.trim() ? 'bg-[#007FFF] shadow-lg shadow-blue-100' : 'bg-slate-200'}`}
                       >
                          {editingTypeIndex !== null ? <Check size={24} strokeWidth={3} /> : <Plus size={24} strokeWidth={3} />}
                       </button>
                    </div>
                 </div>
              </div>

              {/* Managed List Section */}
              <div className="space-y-3 overflow-y-auto no-scrollbar flex-1 pb-6">
                 <div className="flex items-center gap-2 px-1 mb-2">
                    <Layers size={14} className="text-slate-400" />
                    <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Active Types</h3>
                 </div>
                 {tableTypes.map((type, idx) => (
                   <div 
                    key={idx} 
                    className={`flex items-center justify-between p-4 rounded-2xl border transition-all duration-300 ${
                      editingTypeIndex === idx ? 'border-blue-500 bg-blue-50/30' : 'border-slate-50 bg-white hover:bg-slate-50/50'
                    }`}
                   >
                      <div className="flex items-center gap-4">
                         <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${editingTypeIndex === idx ? 'bg-blue-500 text-white' : 'bg-blue-50 text-blue-400'}`}>
                            <Tag size={14} />
                         </div>
                         <span className="text-sm font-bold text-slate-700">{type}</span>
                      </div>
                      <div className="flex items-center gap-1">
                         <button 
                           onClick={() => startEdit(idx)}
                           className="w-10 h-10 rounded-xl flex items-center justify-center text-slate-300 hover:text-blue-500 hover:bg-blue-50 transition-all"
                         >
                            <Pencil size={16} />
                         </button>
                         <button 
                           onClick={() => deleteType(idx)}
                           className="w-10 h-10 rounded-xl flex items-center justify-center text-slate-300 hover:text-rose-500 hover:bg-rose-50 transition-all"
                         >
                            <Trash2 size={16} />
                         </button>
                      </div>
                   </div>
                 ))}
              </div>

              {/* Done Button */}
              <div className="pt-4 shrink-0">
                 <button 
                    onClick={() => setIsManageTypesOpen(false)}
                    className="w-full h-14 bg-[#0F172A] text-white rounded-2xl font-bold text-base shadow-xl active:scale-[0.98] transition-all"
                 >
                    Done
                 </button>
              </div>
           </div>
        </div>
      )}

      {/* Booking Settings Modal */}
      {isBookingSettingsOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-900/10 backdrop-blur-md flex items-end justify-center animate-in fade-in duration-300">
           <div 
             className="w-full max-w-md bg-white rounded-t-[40px] p-8 shadow-[0_-20px_50px_rgba(0,0,0,0.1)] border-t border-slate-100 animate-in slide-in-from-bottom duration-500 ease-out overflow-y-auto max-h-[90vh]"
           >
              {/* Modal Header */}
              <div className="flex items-center justify-between mb-8 shrink-0">
                 <div className="w-10"></div>
                 <div className="text-center flex-1">
                    <h2 className="text-2xl font-black text-[#0F172A] tracking-tight uppercase">Booking Settings</h2>
                    <p className="text-xs font-medium text-slate-400 leading-snug mt-1.5 px-4">
                       Configure default fees for table reservations.
                    </p>
                 </div>
                 <button 
                   onClick={() => setIsBookingSettingsOpen(false)}
                   className="w-10 h-10 flex items-center justify-center text-slate-300 hover:text-slate-900 transition-colors"
                 >
                    <X size={24} />
                 </button>
              </div>

              <div className="space-y-8">
                 {/* Toggle Section */}
                 <div className="flex items-center justify-between p-6 bg-slate-50 rounded-[32px] border border-slate-100">
                    <div className="space-y-1">
                       <h4 className="text-sm font-black text-slate-900 uppercase">Enable Booking Fee</h4>
                       <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Apply to normal bookings</p>
                    </div>
                    <button 
                      onClick={() => setIsBookingFeeEnabled(!isBookingFeeEnabled)}
                      className={`w-14 h-8 rounded-full p-1 transition-all duration-300 relative ${isBookingFeeEnabled ? 'bg-[#007FFF]' : 'bg-slate-200'}`}
                    >
                       <div className={`w-6 h-6 bg-white rounded-full shadow-sm transition-transform duration-300 ${isBookingFeeEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
                    </button>
                 </div>

                 {/* Amount Input */}
                 <div className={`space-y-2 transition-opacity duration-300 ${isBookingFeeEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none'}`}>
                    <label className="text-sm font-bold text-[#0F172A] ml-1">Default Fee Amount (₹)</label>
                    <div className="relative">
                       <IndianRupee className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none" size={18} />
                       <input 
                         type="number" 
                         value={bookingAmount}
                         onChange={(e) => setBookingAmount(e.target.value)}
                         placeholder="e.g., 500"
                         className="w-full h-16 bg-white border border-slate-100 rounded-2xl pl-12 pr-5 text-xl font-black text-slate-900 focus:outline-none focus:border-[#007FFF]/40 transition-all"
                       />
                    </div>
                    <p className="text-[10px] font-medium text-slate-400 uppercase tracking-wide ml-1 mt-2">
                       This amount will be pre-authorized at the time of table booking.
                    </p>
                 </div>

                 {/* Action Buttons */}
                 <div className="pt-4 space-y-3">
                    <button 
                      onClick={() => setIsBookingSettingsOpen(false)}
                      className="w-full h-14 bg-[#007FFF] text-white rounded-2xl font-bold text-base shadow-lg shadow-blue-100 active:scale-[0.98] transition-all"
                    >
                       Save Settings
                    </button>
                    <button 
                      onClick={() => setIsBookingSettingsOpen(false)}
                      className="w-full h-14 bg-white border border-slate-100 text-[#0F172A] rounded-2xl font-bold text-base active:scale-[0.98] transition-all"
                    >
                       Discard
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      <style>{`
        .perspective-1000 {
          perspective: 1000px;
        }
      `}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Plus, 
  Layers, 
  Settings, 
  Users, 
  Clock, 
  Maximize2, 
  Navigation, 
  Circle, 
  Zap, 
  Move,
  LayoutGrid,
  ChevronRight,
  PlusCircle,
  Tag,
  X,
  ChevronDown,
  Trash2,
  Pencil,
  Check,
  Hash,
  Gift,
  Boxes,
  IndianRupee,
  PlusSquare,
  MinusCircle,
  Pause,
  Play,
  Edit3,
  AlertCircle
} from 'lucide-react';

interface Table {
  id: string;
  status: 'Occupied' | 'Open' | 'Reserved';
  capacity: number;
  time?: string;
  guests?: number;
}

interface Zone {
  id: string;
  title: string;
  tables: Table[];
}

interface BookingPackage {
  id: string;
  name: string;
  price: string;
  included: string[];
  excluded: string[];
  status: 'active' | 'paused';
}

export const TableView: React.FC = () => {
  const [activeZone, setActiveZone] = useState<string>('all');
  const [isAddTableOpen, setIsAddTableOpen] = useState(false);
  const [isAddSeriesOpen, setIsAddSeriesOpen] = useState(false);
  const [isManageTypesOpen, setIsManageTypesOpen] = useState(false);
  const [isBookingSettingsOpen, setIsBookingSettingsOpen] = useState(false);
  const [isCreatePackageOpen, setIsCreatePackageOpen] = useState(false);
  const [isManagePackagesOpen, setIsManagePackagesOpen] = useState(false);

  // Table Types State
  const [tableTypes, setTableTypes] = useState(['Normal', 'VIP', 'Outdoor', 'Private']);
  const [newTypeName, setNewTypeName] = useState('');
  const [editingTypeIndex, setEditingTypeIndex] = useState<number | null>(null);

  // Booking Settings State
  const [bookingAmount, setBookingAmount] = useState('500');
  const [isBookingFeeEnabled, setIsBookingFeeEnabled] = useState(true);

  // Packages State
  const [packages, setPackages] = useState<BookingPackage[]>([
    {
      id: 'pkg-1',
      name: 'Birthday Celebration',
      price: '2500',
      included: ['Table Decoration', 'Welcome Drinks', 'Birthday Cake (500g)'],
      excluded: ['Main Course', 'Alcoholic Beverages'],
      status: 'active'
    },
    {
      id: 'pkg-2',
      name: 'Romantic Date',
      price: '1800',
      included: ['Candlelight Setup', '2 Glasses of Wine', 'Appetizer Platter'],
      excluded: ['Dessert', 'Pick & Drop'],
      status: 'active'
    }
  ]);

  // Create/Edit Package Form State
  const [packageForm, setPackageForm] = useState<Partial<BookingPackage>>({
    name: '',
    price: '',
    included: [''],
    excluded: ['']
  });
  const [editingPackageId, setEditingPackageId] = useState<string | null>(null);

  const zones: Zone[] = [
    {
      id: 'normal',
      title: 'Grand Hall',
      tables: [
        { id: 'T1', status: 'Occupied', capacity: 4, guests: 3, time: '45m' },
        { id: 'T4', status: 'Occupied', capacity: 4, guests: 4, time: '12m' },
        { id: 'T6', status: 'Open', capacity: 4 },
      ]
    },
    {
      id: 'couple',
      title: 'Romantic Wing',
      tables: [
        { id: 'C1', status: 'Open', capacity: 2 },
        { id: 'C2', status: 'Open', capacity: 2 },
        { id: 'C3', status: 'Occupied', capacity: 2, guests: 2, time: '22m' },
      ]
    },
    {
      id: 'family',
      title: 'Family Loft',
      tables: [
        { id: 'F1', status: 'Reserved', capacity: 6, time: '19:00' },
        { id: 'F2', status: 'Open', capacity: 8 },
      ]
    },
    {
      id: 'private',
      title: 'Executive Suite',
      tables: [
        { id: 'P1', status: 'Open', capacity: 8 },
      ]
    }
  ];

  const blueColor = '#007FFF';

  const filteredZones = activeZone === 'all' 
    ? zones 
    : zones.filter(z => z.id === activeZone);

  const handleAddOrUpdateType = () => {
    if (!newTypeName.trim()) return;

    if (editingTypeIndex !== null) {
      const updated = [...tableTypes];
      updated[editingTypeIndex] = newTypeName.trim();
      setTableTypes(updated);
      setEditingTypeIndex(null);
    } else {
      setTableTypes([...tableTypes, newTypeName.trim()]);
    }
    setNewTypeName('');
  };

  const deleteType = (index: number) => {
    setTableTypes(tableTypes.filter((_, i) => i !== index));
    if (editingTypeIndex === index) {
      setEditingTypeIndex(null);
      setNewTypeName('');
    }
  };

  const startEdit = (index: number) => {
    setEditingTypeIndex(index);
    setNewTypeName(tableTypes[index]);
  };

  // Package Handlers
  const handleSavePackage = () => {
    if (!packageForm.name || !packageForm.price) return;

    if (editingPackageId) {
      setPackages(prev => prev.map(p => p.id === editingPackageId ? { ...p, ...packageForm as BookingPackage } : p));
    } else {
      const newPkg: BookingPackage = {
        id: `pkg-${Date.now()}`,
        name: packageForm.name!,
        price: packageForm.price!,
        included: (packageForm.included || []).filter(i => i.trim()),
        excluded: (packageForm.excluded || []).filter(i => i.trim()),
        status: 'active'
      };
      setPackages(prev => [...prev, newPkg]);
    }
    closePackageModal();
  };

  const closePackageModal = () => {
    setIsCreatePackageOpen(false);
    setPackageForm({ name: '', price: '', included: [''], excluded: [''] });
    setEditingPackageId(null);
  };

  const startEditPackage = (pkg: BookingPackage) => {
    setPackageForm({ ...pkg });
    setEditingPackageId(pkg.id);
    setIsManagePackagesOpen(false);
    setIsCreatePackageOpen(true);
  };

  const deletePackage = (id: string) => {
    setPackages(prev => prev.filter(p => p.id !== id));
  };

  const togglePackageStatus = (id: string) => {
    setPackages(prev => prev.map(p => p.id === id ? { ...p, status: p.status === 'active' ? 'paused' : 'active' } : p));
  };

  const updateListField = (type: 'included' | 'excluded', index: number, value: string) => {
    const list = [...(packageForm[type] || [])];
    list[index] = value;
    setPackageForm({ ...packageForm, [type]: list });
  };

  const addListItem = (type: 'included' | 'excluded') => {
    setPackageForm({ ...packageForm, [type]: [...(packageForm[type] || []), ''] });
  };

  const removeListItem = (type: 'included' | 'excluded', index: number) => {
    const list = [...(packageForm[type] || [])];
    if (list.length > 1) {
      list.splice(index, 1);
      setPackageForm({ ...packageForm, [type]: list });
    }
  };

  return (
    <div className="pb-40 bg-[#F8FAFC] min-h-screen font-sans animate-in fade-in duration-700 overflow-x-hidden">

      {/* 1. Header & Technical HUD */}
      <div className="px-6 pt-10 pb-8 bg-white border-b border-slate-100 sticky top-0 z-40">
        <div className="flex items-center justify-between mb-8">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
               <span className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></span>
               <p className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em]">System Online</p>
            </div>
            <h1 className="text-4xl font-black text-slate-900 tracking-tighter leading-none">Tables</h1>
          </div>
          <button className="w-12 h-12 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center text-slate-400 active:scale-90 transition-all hover:bg-slate-100">
             <Maximize2 size={20} />
          </button>
        </div>

        {/* Action Buttons Grid */}
        <div className="grid grid-cols-2 gap-3 mb-6">
           <button 
             onClick={() => setIsAddTableOpen(true)}
             className="flex items-center justify-center gap-3 bg-[#007FFF] text-white py-4 rounded-[20px] shadow-lg shadow-blue-100 active:scale-[0.98] transition-all"
           >
              <PlusCircle size={20} strokeWidth={2.5} />
              <span className="text-sm font-bold tracking-tight">Add Table</span>
           </button>
           <button 
             onClick={() => setIsAddSeriesOpen(true)}
             className="flex items-center justify-center gap-3 bg-white border border-slate-100 text-slate-900 py-4 rounded-[20px] shadow-sm active:scale-[0.98] transition-all"
           >
              <Plus size={20} strokeWidth={2.5} />
              <span className="text-sm font-bold tracking-tight">Add Series</span>
           </button>
           <button 
             onClick={() => setIsManageTypesOpen(true)}
             className="flex items-center justify-center gap-3 bg-white border border-slate-100 text-slate-900 py-4 rounded-[20px] shadow-sm active:scale-[0.98] transition-all"
           >
              <Tag size={20} strokeWidth={2.5} />
              <span className="text-sm font-bold tracking-tight">Manage Types</span>
           </button>
           <button 
             onClick={() => setIsBookingSettingsOpen(true)}
             className="flex items-center justify-center gap-3 bg-white border border-slate-100 text-slate-900 py-4 rounded-[20px] shadow-sm active:scale-[0.98] transition-all"
           >
              <Settings size={20} strokeWidth={2.5} />
              <span className="text-sm font-bold tracking-tight">Booking Settings</span>
           </button>
           <button 
             onClick={() => setIsCreatePackageOpen(true)}
             className="flex items-center justify-center gap-3 bg-white border border-slate-100 text-slate-900 py-4 rounded-[20px] shadow-sm active:scale-[0.98] transition-all"
           >
              <Gift size={20} strokeWidth={2.5} />
              <span className="text-sm font-bold tracking-tight">Create Package</span>
           </button>
           <button 
             onClick={() => setIsManagePackagesOpen(true)}
             className="flex items-center justify-center gap-3 bg-white border border-slate-100 text-slate-900 py-4 rounded-[20px] shadow-sm active:scale-[0.98] transition-all"
           >
              <Boxes size={20} strokeWidth={2.5} />
              <span className="text-sm font-bold tracking-tight">Manage Packages</span>
           </button>
        </div>

        {/* HUD Stats */}
        <div className="grid grid-cols-3 gap-3">
           <div className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm">
              <p className="text-[9px] font-black text-slate-400 uppercase mb-1.5 tracking-wider">Free</p>
              <div className="flex items-baseline gap-1">
                <p className="text-2xl font-black text-slate-900 leading-none">09</p>
                <div className="w-1.5 h-1.5 rounded-full bg-[#007FFF]"></div>
              </div>
           </div>
           <div className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm">
              <p className="text-[9px] font-black text-slate-400 uppercase mb-1.5 tracking-wider">Busy</p>
              <div className="flex items-baseline gap-1">
                <p className="text-2xl font-black text-rose-500 leading-none">03</p>
                <div className="w-1.5 h-1.5 rounded-full bg-rose-500"></div>
              </div>
           </div>
           <div className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm">
              <p className="text-[9px] font-black text-slate-400 uppercase mb-1.5 tracking-wider">Booked</p>
              <div className="flex items-baseline gap-1">
                <p className="text-2xl font-black text-amber-500 leading-none">01</p>
                <div className="w-1.5 h-1.5 rounded-full bg-amber-500"></div>
              </div>
           </div>
        </div>

        {/* Zone Filters */}
        <div className="flex gap-2 overflow-x-auto no-scrollbar mt-8 -mx-1 px-1">
           {['all', ...zones.map(z => z.id)].map(id => (
             <button 
               key={id}
               onClick={() => setActiveZone(id)}
               className={`flex-shrink-0 px-6 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border ${
                 activeZone === id 
                  ? 'bg-slate-900 border-slate-900 text-white shadow-xl shadow-slate-200' 
                  : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'
               }`}
             >
               {id === 'all' ? 'Floor Plan' : zones.find(z => z.id === id)?.title}
             </button>
           ))}
        </div>
      </div>

      {/* 2. Isometric Floor Plan */}
      <div className="relative p-6">
        <div className="absolute inset-0 z-0 opacity-40 pointer-events-none" 
          style={{ 
            backgroundImage: `radial-gradient(#CBD5E1 1px, transparent 1px)`,
            backgroundSize: '24px 24px'
          }} 
        />

        <div className="relative z-10 space-y-24 pt-4">
          {filteredZones.map((zone, zIdx) => (
            <div key={zone.id} className="animate-in fade-in slide-in-from-bottom-8 duration-700" style={{ animationDelay: `${zIdx * 100}ms` }}>
              <div className="flex items-center gap-4 mb-14">
                <div className="w-10 h-10 rounded-xl bg-white flex items-center justify-center text-slate-900 border border-slate-100 shadow-sm">
                  <Navigation size={18} className="rotate-45" />
                </div>
                <h3 className="text-[13px] font-black text-slate-900 uppercase tracking-[0.4em]">{zone.title}</h3>
                <div className="flex-1 h-[1px] bg-slate-200"></div>
              </div>

              <div className="grid grid-cols-2 gap-x-8 gap-y-20">
                {zone.tables.map((table) => (
                  <div key={table.id} className="group relative perspective-1000">
                    <div 
                      className="relative w-full aspect-square transition-all duration-500 ease-out active:scale-95"
                      style={{ 
                        transformStyle: 'preserve-3d',
                        transform: 'rotateX(50deg) rotateZ(-30deg)'
                      }}
                    >
                      <div className="absolute inset-4 bg-slate-900/10 blur-2xl rounded-[32px] translate-y-8 translate-x-4 opacity-40 group-hover:opacity-60 transition-opacity"></div>
                      <div className={`absolute -inset-4 rounded-[40px] blur-2xl opacity-0 group-hover:opacity-20 transition-opacity duration-700 ${
                        table.status === 'Occupied' ? 'bg-rose-500' : table.status === 'Reserved' ? 'bg-amber-500' : 'bg-blue-500'
                      }`}></div>
                      <div className={`absolute inset-0 rounded-[32px] translate-z-[-20px] border-b-[6px] ${
                        table.status === 'Occupied' ? 'bg-rose-100 border-rose-200' : 
                        table.status === 'Reserved' ? 'bg-amber-100 border-amber-200' : 
                        'bg-slate-100 border-slate-200'
                      }`}></div>
                      <div className={`absolute inset-0 rounded-[32px] border flex flex-col items-center justify-center transition-all duration-500 shadow-[0_10px_40px_rgba(0,0,0,0.03)] ${
                        table.status === 'Occupied' ? 'bg-white border-rose-200' : 
                        table.status === 'Reserved' ? 'bg-white border-amber-200' : 
                        'bg-white border-slate-100 hover:border-blue-200'
                      }`}>
                        <div className="flex flex-col items-center" style={{ transform: 'rotateZ(30deg) rotateX(-50deg)' }}>
                          <span className={`text-[9px] font-black uppercase tracking-[0.2em] mb-1.5 ${
                             table.status === 'Open' ? 'text-slate-300' : 'text-slate-400'
                          }`}>{table.id}</span>
                          <div className="flex items-center gap-2">
                             <Users size={16} className={`${table.status === 'Occupied' ? 'text-rose-500' : table.status === 'Reserved' ? 'text-amber-500' : 'text-slate-300'}`} strokeWidth={3} />
                             <span className={`text-2xl font-black tracking-tighter ${
                                table.status === 'Open' ? 'text-slate-300' : 'text-slate-900'
                             }`}>
                                {table.guests || table.capacity}
                                <span className="text-xs text-slate-300 ml-0.5 font-bold">/{table.capacity}</span>
                             </span>
                          </div>
