                <h3 className="text-[13px] font-black text-slate-900 uppercase tracking-[0.4em]">{zone.title}</h3>
                <div className="flex-1 h-[1px] bg-slate-200"></div>
              </div>

              <div className="grid grid-cols-2 gap-x-8 gap-y-20">
                {zone.tables.map((table) => (
                  <div key={table.id} className="group relative perspective-1000">
                    <div 
                      className="relative w-full aspect-square transition-all duration-500 ease-out active:scale-95"
                      style={{ 
                        transformStyle: 'preserve-3d',
                        transform: 'rotateX(50deg) rotateZ(-30deg)'
