                    >
                      <div className={`absolute inset-0 rounded-[32px] translate-z-[-20px] border-b-[6px] ${
                        table.status === 'Occupied' ? 'bg-rose-100 border-rose-200' : 
                        table.status === 'Reserved' ? 'bg-amber-100 border-amber-200' : 
                        'bg-slate-100 border-slate-200'
