                      <div className={`absolute inset-0 rounded-[32px] border flex flex-col items-center justify-center transition-all duration-500 ${
                        table.status === 'Occupied' ? 'bg-white border-rose-200' : 
                        table.status === 'Reserved' ? 'bg-white border-amber-200' : 
                        'bg-white border-slate-100 hover:border-blue-200'
                      }`}>
                        <div className="flex flex-col items-center" style={{ transform: 'rotateZ(30deg) rotateX(-50deg)' }}>
                          <span className={`text-[9px] font-black uppercase tracking-[0.2em] mb-1.5 ${
