                          <div className="flex items-center gap-2">
                             <Users size={16} className={`${table.status === 'Occupied' ? 'text-rose-500' : table.status === 'Reserved' ? 'text-amber-500' : 'text-slate-300'}`} strokeWidth={3} />
                             <span className={`text-2xl font-black tracking-tighter ${
                                table.status === 'Open' ? 'text-slate-300' : 'text-slate-900'
