                    <div className="mt-6 text-center space-y-1">
                       <div className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-slate-100 rounded-full">
                          <Circle size={8} fill={table.status === 'Occupied' ? '#F43F5E' : table.status === 'Reserved' ? '#F59E0B' : '#CBD5E1'} className="border-none" />
                          <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest">{table.status}</span>
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
