           <div 
             className="w-full max-w-md bg-white rounded-t-[40px] p-8 border-t border-slate-100 animate-in slide-in-from-bottom duration-500 ease-out overflow-y-auto max-h-[90vh]"
           >
              {/* Modal Header */}
              <div className="flex items-center justify-between mb-8">
