                 >
                    <X size={24} />
                 </button>
              </div>

              <div className="space-y-6">
                 {/* Table Name */}
                 <div className="space-y-2">
                    <label className="text-sm font-bold text-[#0F172A]">Table Name / ID</label>
                    <input 
                      type="text" 
                      placeholder="e.g., T-12, VIP-1"
                      className="w-full h-14 bg-white border border-[#007FFF] rounded-2xl px-5 text-slate-600 font-medium focus:outline-none focus:ring-2 focus:ring-[#007FFF]/20"
                    />
                 </div>

                 {/* Capacity */}
                 <div className="space-y-2">
                    <label className="text-sm font-bold text-[#0F172A]">Table Capacity</label>
                    <div className="relative">
                       <Users className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none" size={18} />
                       <input 
                         type="number" 
                         placeholder="e.g., 4"
                         className="w-full h-14 bg-white border border-slate-100 rounded-2xl pl-12 pr-5 text-slate-600 font-medium focus:outline-none focus:bg-slate-50"
                       />
                    </div>
                 </div>

                 {/* Type Select */}
                 <div className="space-y-2">
                    <label className="text-sm font-bold text-[#0F172A]">Type of table</label>
                    <div className="relative">
                       <select className="w-full h-14 bg-white border border-slate-100 rounded-2xl px-5 text-slate-600 font-medium focus:outline-none appearance-none cursor-pointer">
                          {tableTypes.map(type => (
                             <option key={type}>{type}</option>
                          ))}
                       </select>
                       <ChevronDown className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={20} />
                    </div>
                 </div>

                 {/* Action Buttons */}
                 <div className="pt-4 space-y-3">
                    <button 
                      onClick={() => setIsAddTableOpen(false)}
                      className="w-full h-14 bg-[#007FFF] text-white rounded-2xl font-bold text-base active:scale-[0.98] transition-all"
                    >
                       Add Table
                    </button>
                    <button 
                      onClick={() => setIsAddTableOpen(false)}
                      className="w-full h-14 bg-white border border-slate-100 text-[#0F172A] rounded-2xl font-bold text-base active:scale-[0.98] transition-all"
                    >
                       Cancel
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

