const ChangePasswordCard: React.FC = () => {
  const [step, setStep] = useState<'idle' | 'email' | 'otp' | 'new' | 'success'>('idle');
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');
  const [showPass, setShowPass] = useState(false);

  const getStrength = (p: string) => {
    if (!p) return null;
    if (p.length < 6) return { label: 'Weak', color: 'text-rose-500', bg: 'bg-rose-500' };
    if (p.length < 10) return { label: 'Medium', color: 'text-amber-500', bg: 'bg-amber-500' };
    return { label: 'Strong', color: 'text-emerald-500', bg: 'bg-emerald-500' };
  };

  const strength = getStrength(newPass);

  const handleReset = () => {
    setStep('idle');
    setEmail('');
    setOtp('');
    setNewPass('');
    setConfirmPass('');
  };

  return (
    <div className="bg-white rounded-[32px] border border-slate-100 p-6 space-y-6">
      {step === 'idle' && (
        <button 
          onClick={() => setStep('email')}
          className="w-full flex items-center justify-between group"
        >
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl bg-blue-50 flex items-center justify-center text-blue-500">
              <KeyRound size={20} />
            </div>
            <div className="text-left">
              <p className="text-base font-bold text-slate-900 leading-none">Forget Password</p>
              <p className="text-[11px] font-semibold text-slate-400 mt-2">Reset your security credentials</p>
            </div>
          </div>
          <ChevronRight size={18} className="text-slate-300 group-hover:text-slate-900 transition-colors" />
        </button>
      )}

      {step === 'email' && (
        <div className="space-y-4 animate-in fade-in zoom-in-95 duration-300">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Registered Email</label>
            <input 
              type="email" 
              placeholder="admin@crevings.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
            />
          </div>
          <button 
            disabled={!email.includes('@')}
            onClick={() => setStep('otp')}
            style={{ backgroundColor: blueColor }}
            className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all"
          >
            Send Verification Code
          </button>
        </div>
      )}

      {step === 'otp' && (
        <div className="space-y-4 animate-in fade-in zoom-in-95 duration-300">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 text-center block">Enter 6-Digit OTP</label>
            <input 
              type="text" 
              placeholder="0 0 0 0 0 0"
              maxLength={6}
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              className="w-full h-16 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-2xl font-black text-center text-slate-900 tracking-[0.5em] focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
            />
          </div>
          <button 
            disabled={otp.length !== 6}
            onClick={() => setStep('new')}
            style={{ backgroundColor: blueColor }}
            className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all"
          >
            Verify Code
          </button>
        </div>
      )}

      {step === 'new' && (
        <div className="space-y-5 animate-in fade-in zoom-in-95 duration-300">
          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">New Password</label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"}
                  placeholder="••••••••"
                  value={newPass}
                  onChange={(e) => setNewPass(e.target.value)}
                  className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 pr-12 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
                />
                <button 
                  onClick={() => setShowPass(!showPass)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300"
                >
                  {showPass ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
              {strength && (
                <div className="flex items-center gap-2 mt-2 ml-1">
                  <div className="flex-1 h-1 bg-slate-100 rounded-full overflow-hidden">
                    <div className={`h-full ${strength.bg} transition-all duration-500`} style={{ width: strength.label === 'Strong' ? '100%' : strength.label === 'Medium' ? '60%' : '30%' }}></div>
                  </div>
                  <span className={`text-[9px] font-black uppercase tracking-widest ${strength.color}`}>{strength.label}</span>
                </div>
              )}
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Confirm Password</label>
              <input 
                type={showPass ? "text" : "password"}
                placeholder="••••••••"
                value={confirmPass}
                onChange={(e) => setConfirmPass(e.target.value)}
                className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
              />
            </div>
          </div>
          <button 
            disabled={!newPass || newPass !== confirmPass || strength?.label === 'Weak'}
            onClick={() => setStep('success')}
            style={{ backgroundColor: blueColor }}
            className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all"
          >
            Update Password
          </button>
        </div>
      )}

      {step === 'success' && (
        <div className="text-center space-y-4 py-4 animate-in zoom-in-95 duration-500">
          <div className="w-16 h-16 bg-emerald-50 rounded-full flex items-center justify-center text-emerald-500 mx-auto border border-emerald-100">
            <CheckCircle2 size={32} />
          </div>
          <div>
            <p className="text-base font-bold text-slate-900">Security Updated</p>
            <p className="text-[11px] font-semibold text-slate-400 mt-1">Your new password is now active.</p>
          </div>
          <button onClick={handleReset} className="text-[10px] font-black text-blue-500 uppercase tracking-[0.2em] pt-2">Finish</button>
        </div>
      )}
    </div>
  );
};

