          <div className="space-y-4">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">New Password</label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"}
                  placeholder="••••••••"
                  value={newPass}
                  onChange={(e) => setNewPass(e.target.value)}
                  className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 pr-12 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
                />
                <button 
                  onClick={() => setShowPass(!showPass)}
                  className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300"
                >
                  {showPass ? <EyeOff size={18} /> : <Eye size={18} />}
                </button>
              </div>
              {strength && (
                <div className="flex items-center gap-2 mt-2 ml-1">
                  <div className="flex-1 h-1 bg-slate-100 rounded-full overflow-hidden">
                    <div className={`h-full ${strength.bg} transition-all duration-500`} style={{ width: strength.label === 'Strong' ? '100%' : strength.label === 'Medium' ? '60%' : '30%' }}></div>
                  </div>
                  <span className={`text-[9px] font-black uppercase tracking-widest ${strength.color}`}>{strength.label}</span>
                </div>
              )}
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Confirm Password</label>
              <input 
                type={showPass ? "text" : "password"}
                placeholder="••••••••"
                value={confirmPass}
                onChange={(e) => setConfirmPass(e.target.value)}
                className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
              />
            </div>
          </div>
          <button 
            disabled={!newPass || newPass !== confirmPass || strength?.label === 'Weak'}
            onClick={() => setStep('success')}
            style={{ backgroundColor: blueColor }}
            className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all"
          >
            Update Password
          </button>
        </div>
      )}

      {step === 'success' && (
        <div className="text-center space-y-4 py-4 animate-in zoom-in-95 duration-500">
          <div className="w-16 h-16 bg-emerald-50 rounded-full flex items-center justify-center text-emerald-500 mx-auto border border-emerald-100">
            <CheckCircle2 size={32} />
          </div>
          <div>
            <p className="text-base font-bold text-slate-900">Security Updated</p>
            <p className="text-[11px] font-semibold text-slate-400 mt-1">Your new password is now active.</p>
          </div>
          <button onClick={handleReset} className="text-[10px] font-black text-blue-500 uppercase tracking-[0.2em] pt-2">Finish</button>
        </div>
      )}
    </div>
  );
};

const AccountInfoCard: React.FC = () => {
  const [activeEdit, setActiveEdit] = useState<'email' | 'phone' | 'google' | null>(null);
  const [step, setStep] = useState<'auth' | 'input'>('auth');
  const [inputVal, setInputVal] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [otpError, setOtpError] = useState(false);
  const otpInputs = useRef<(HTMLInputElement | null)[]>([]);

  const accountData = {
    email: 'admin@gkitchen.com',
    phone: '+91 9876543210',
    google: 'Gourmet Kitchen HQ'
  };

  const handleStartEdit = (type: 'email' | 'phone' | 'google') => {
    setActiveEdit(type);
    setStep('auth');
    setOtp(['', '', '', '', '', '']);
    setOtpError(false);
    setInputVal('');
  };

  const handleOtpChange = (value: string, index: number) => {
    if (isNaN(Number(value))) return;
    setOtpError(false);

    const newOtp = [...otp];
    newOtp[index] = value.substring(value.length - 1);
    setOtp(newOtp);

    if (value && index < 5) {
      otpInputs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpInputs.current[index - 1]?.focus();
    }
  };

  const handleVerify = () => {
    const enteredOtp = otp.join('');
    if (enteredOtp === '123456') { // Demo OTP
      setStep('input');
    } else {
      setOtpError(true);
    }
  };

  const handleCommit = () => {
    setActiveEdit(null);
  };

  return (
    <div className="bg-white rounded-[40px] border border-slate-100 p-8 space-y-8">
      <div className="space-y-6">
        {[
          { id: 'email', label: 'Email Address', val: accountData.email, icon: Mail },
          { id: 'phone', label: 'Phone Number', val: accountData.phone, icon: Smartphone },
          { id: 'google', label: 'Google Account', val: accountData.google, icon: ShieldCheck },
        ].map(item => (
          <div key={item.id} className="flex items-center justify-between border-b border-slate-50 last:border-0 pb-6 last:pb-0">
            <div className="flex items-center gap-4">
              <div className="w-11 h-11 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100">
                <item.icon size={18} />
              </div>
              <div>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">{item.label}</p>
                <p className="text-sm font-bold text-slate-900">{item.val}</p>
              </div>
            </div>
            <button 
              onClick={() => handleStartEdit(item.id as any)}
              className="px-4 py-2 bg-blue-50 text-blue-600 rounded-xl text-[10px] font-black uppercase tracking-widest border border-blue-100 active:scale-95 transition-all"
            >
              Change
            </button>
          </div>
        ))}
      </div>

      {activeEdit && (
        <div className="fixed inset-0 z-[200] bg-slate-900/10 backdrop-blur-md flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white rounded-[40px] w-full max-w-sm p-8 space-y-6 relative border border-slate-100">
            <button 
              onClick={() => setActiveEdit(null)}
              className="absolute top-6 right-6 p-2 text-slate-300 hover:text-slate-900"
            >
              <X size={20} />
            </button>

            <div className="text-center space-y-2">
              <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">Update {activeEdit}</h3>
              <p className="text-[10px] font-semibold text-slate-400 uppercase tracking-widest">
                {step === 'auth' ? 'Verification Required' : `Enter New ${activeEdit}`}
              </p>
            </div>

            {step === 'auth' ? (
              <div className="space-y-6">
                <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block text-center">Enter 6-digit OTP</label>
                  <div className="flex justify-between gap-2">
                    {otp.map((digit, index) => (
                      <input
                        key={index}
                        ref={(el) => (otpInputs.current[index] = el)}
                        type="tel"
                        maxLength={1}
                        value={digit}
                        onChange={(e) => handleOtpChange(e.target.value, index)}
                        onKeyDown={(e) => handleKeyDown(e, index)}
                        className={`w-10 h-14 text-center text-xl font-black rounded-xl border transition-all focus:outline-none ${
                          otpError 
                          ? 'border-rose-300 bg-rose-50 text-rose-600' 
                          : digit ? 'border-slate-900 bg-white text-slate-900 shadow-sm' : 'border-slate-200 bg-slate-50 focus:border-slate-400'
                        }`}
                      />
                    ))}
                  </div>
                  {otpError && <p className="text-rose-500 text-[10px] font-bold text-center uppercase tracking-widest animate-in fade-in">Invalid Code</p>}
                </div>
                <button 
                  onClick={handleVerify}
                  disabled={otp.join('').length < 6}
                  style={{ backgroundColor: blueColor }}
                  className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all shadow-lg shadow-blue-100"
                >
                  Verify Code
                </button>
              </div>
            ) : (
              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">New {activeEdit}</label>
                  <input 
                    type={activeEdit === 'phone' ? 'tel' : 'text'}
                    placeholder={`Enter new ${activeEdit}`}
                    value={inputVal}
                    onChange={(e) => setInputVal(e.target.value)}
                    className="w-full h-14 bg-slate-50 border border-slate-100 rounded-2xl px-5 text-sm font-bold text-slate-900 focus:outline-none focus:bg-white focus:border-blue-500 transition-all"
                  />
                </div>
                <button 
                  onClick={handleCommit}
                  style={{ backgroundColor: blueColor }}
                  className="w-full h-14 rounded-2xl text-white font-black text-[11px] uppercase tracking-widest disabled:opacity-30 active:scale-95 transition-all"
                >
                  Confirm Change
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

