  { id: 'ORD-015', time: '08:20', customer: 'Amit Sharma', total: '450.00', items: '2 Items • Veg Burger Meal', channel: 'Zomato', status: 'Cooking', type: 'Takeaway' },
  { id: 'ORD-022', time: '15:10', customer: 'Table 4', total: '1,250.00', items: '3 Items • Family Feast', channel: 'Internal', status: 'Ready', type: 'Dine-in' }
];

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(true);
  const [currentTab, setCurrentTab] = useState<Tab>(Tab.HOME);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isOnline, setIsOnline] = useState(true);
  const [rushHour, setRushHour] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [selectedBranch, setSelectedBranch] = useState(BRANCHES[0]);
  const [quickOrderType, setQuickOrderType] = useState<'Takeaway' | 'Dine-in' | null>(null);
  const [orders, setOrders] = useState<Order[]>(INITIAL_ORDERS);

  const handleAddOrder = (newOrder: Order) => {
    setOrders(prev => [newOrder, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string) => {
    setOrders(prev => {
      const orderIndex = prev.findIndex(o => o.id === orderId);
      if (orderIndex === -1) return prev;

      const order = prev[orderIndex];
      let nextStatus = order.status;

      if (order.status === 'Incoming' || order.status === 'Accepted') nextStatus = 'Preparing';
      else if (order.status === 'Preparing' || order.status === 'Cooking') nextStatus = 'Ready';
      else if (order.status === 'Ready') nextStatus = 'Completed';

      if (nextStatus === 'Completed') {
        return prev.filter(o => o.id !== orderId);
      }

      const updatedOrders = [...prev];
      updatedOrders[orderIndex] = { ...order, status: nextStatus };
      return updatedOrders;
    });
  };

  const renderContent = () => {
    switch (currentTab) {
      case Tab.HOME:
        return (
          <Dashboard 
            orders={orders}
            onAddOrder={handleAddOrder}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onNavigateToOrders={() => setCurrentTab(Tab.ORDERS)} 
            onNavigateToTables={() => setCurrentTab(Tab.TABLES)}
            onQuickOrder={(type) => setQuickOrderType(type)}
            isOnline={isOnline}
            setIsOnline={setIsOnline}
            rushHour={rushHour}
            setRushHour={setRushHour}
            selectedBranch={selectedBranch}
          />
        );
      case Tab.ORDERS:
        return <OrdersView orders={orders} onUpdateOrderStatus={handleUpdateOrderStatus} />;
      case Tab.EARNINGS:
        return <EarningsView />;
      case Tab.ANALYTICS:
        return <AnalyticsView />;
      case Tab.MENU:
        return <MenuView />;
      case Tab.PROFILE:
        return <ProfileView 
          onNavigateToTab={(tab) => setCurrentTab(tab)} 
          onLogout={() => setIsLoggedIn(false)}
        />;
      case Tab.SUBSCRIPTION:
        return <SubscriptionView onBack={() => setCurrentTab(Tab.PROFILE)} />;
      case Tab.SETTINGS:
        return <SettingsView />;
      case Tab.ADS_MARKETING:
        return <AdsMarketingView />;
      case Tab.OFFERS:
        return <OffersView />;
      case Tab.CREATE_OFFER:
        return <CreateOfferView />;
      case Tab.OUTLET:
        return <StoreView />;
      case Tab.TABLES:
        return <TableView />;
      case Tab.REFUNDS:
        return <RefundsView />;
      case Tab.NOTIFICATIONS:
        return <NotificationsView onBack={() => setCurrentTab(Tab.HOME)} />;
      case Tab.INTEGRATIONS:
        return <IntegrationsView onBack={() => setCurrentTab(Tab.PROFILE)} />;
      case Tab.SALES_REPORT:
        return <SalesReportView />;
      case Tab.CUSTOMER_DATA:
        return (
          <div className="flex flex-col items-center justify-center h-[70vh] text-slate-400 animate-in fade-in">
            <h2 className="text-xl font-bold text-slate-900 mb-2">Customer Data</h2>
            <p>Database of loyal customers and dining habits.</p>
          </div>
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-[70vh] text-slate-400 animate-in fade-in">
            <p>Coming Soon</p>
          </div>
        );
    }
  };

  if (!isLoggedIn) {
    return <LoginView onLogin={() => setIsLoggedIn(true)} />;
  }

  return (
    <HashRouter>
      <div className="min-h-screen bg-white relative z-10 overflow-x-hidden">
        <div className="bg-white min-h-screen">
          <Header 
            onMenuClick={() => setIsSidebarOpen(true)} 
            onNotificationClick={() => setCurrentTab(Tab.NOTIFICATIONS)}
            isOnline={isOnline}
            onToggleOnline={() => setIsOnline(!isOnline)}
            rushHour={rushHour}
            onToggleRush={() => setRushHour(!rushHour)}
            isPaused={isPaused}
            onTogglePause={() => setIsPaused(!isPaused)}
          />

          <Sidebar 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
            currentTab={currentTab}
            onTabChange={setCurrentTab}
            branches={BRANCHES}
            selectedBranch={selectedBranch}
            onBranchChange={setSelectedBranch}
          />

          <main className="max-w-md mx-auto w-full relative">
            <div className="transition-opacity duration-300">
              {renderContent()}
            </div>
          </main>
        </div>

        <BottomNav currentTab={currentTab} onTabChange={setCurrentTab} />

        {/* Quick Order Overlay */}
        {quickOrderType && (
            <QuickOrderView 
                type={quickOrderType} 
                onBack={() => setQuickOrderType(null)} 
            />
        )}
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        body {
          background-color: #FFFFFF;
          -webkit-tap-highlight-color: transparent;
        }
        main {
          -webkit-overflow-scrolling: touch;
        }
      `}} />
    </HashRouter>
  );
};

