const TABLES = Array.from({ length: 12 }, (_, i) => `T${i + 1}`);

export const QuickOrderView: React.FC<QuickOrderViewProps> = ({ type, onBack }) => {
  const [step, setStep] = useState<'setup' | 'menu' | 'review' | 'payment'>(type === 'Dine-in' ? 'setup' : 'menu');
  const [activeCategory, setActiveCategory] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<Record<number, number>>({});

  // Dine-in Specific State
  const [selectedTables, setSelectedTables] = useState<string[]>([]);
  const [guestCount, setGuestCount] = useState(1);

  // Checkout State
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  const [prepTime, setPrepTime] = useState(15);
  const [paymentStatus, setPaymentStatus] = useState<'paid' | 'unpaid' | null>(null);
  const [paymentMethod, setPaymentMethod] = useState<string | null>(null);
  const [isSuccess, setIsSuccess] = useState(false);

  // Validation States
  const [nameError, setNameError] = useState(false);
  const [phoneError, setPhoneError] = useState(false);

  const categories = ['All', 'Pizza', 'Burgers', 'Salads'];
  const blueColor = '#007FFF';

  const toggleTable = (t: string) => {
    setSelectedTables(prev => 
      prev.includes(t) ? prev.filter(item => item !== t) : [...prev, t]
    );
  };

  const addToCart = (id: number) => {
    setCart(prev => ({ ...prev, [id]: (prev[id] || 0) + 1 }));
  };

  const removeFromCart = (id: number) => {
    setCart(prev => {
      const newCart = { ...prev };
      if (newCart[id] > 1) {
        newCart[id] -= 1;
      } else {
        delete newCart[id];
      }
      return newCart;
    });
  };

  const totalItems = (Object.values(cart) as number[]).reduce((a: number, b: number) => a + b, 0);
  const subtotal = PRODUCTS.reduce((acc, p) => acc + (cart[p.id] || 0) * p.price, 0);
  const tax = subtotal * 0.05;
  const totalPrice = subtotal + tax;

  const handleReviewProceed = () => {
    let valid = true;
    if (!customerName.trim()) {
      setNameError(true);
      valid = false;
    } else {
      setNameError(false);
    }
    if (customerPhone.length < 10) {
      setPhoneError(true);
      valid = false;
    } else {
      setPhoneError(false);
    }

    if (valid) {
      setStep('payment');
    }
  };

  const handleCompleteOrder = () => {
    setIsSuccess(true);
    setTimeout(() => {
      onBack();
    }, 2000);
  };

  const filteredProducts = PRODUCTS.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.category.toLowerCase().includes(searchQuery.toLowerCase())
  );

  if (isSuccess) {
    return (
      <div className="fixed inset-0 z-[300] bg-[#007FFF] flex flex-col items-center justify-center p-8 animate-in fade-in duration-500">
        <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-6 animate-bounce">
          <CheckCircle2 size={48} className="text-[#007FFF]" strokeWidth={3} />
        </div>
        <h2 className="text-3xl font-black text-white text-center tracking-tighter uppercase mb-2">Order Confirmed</h2>
        <p className="text-white/80 text-center font-medium mb-8">
            {paymentStatus === 'unpaid' ? 'Unpaid order added to Active Bills' : 'Payment verified successfully'}
        </p>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-[200] bg-[#FBFCFE] flex flex-col animate-in slide-in-from-bottom duration-500 overflow-hidden font-sans">
      {/* Header */}
      <div className="bg-white px-6 pt-6 pb-4 space-y-4 sticky top-0 z-50 border-b border-slate-100">
        <div className="flex items-center justify-between">
            <button 
              onClick={() => {
                  if (step === 'setup') onBack();
                  else if (step === 'menu') setStep(type === 'Dine-in' ? 'setup' : 'menu');
                  else if (step === 'review') setStep('menu');
                  else setStep('review');
              }} 
              className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center text-slate-400 border border-slate-100"
            >
                <ArrowLeft size={20} />
            </button>
            <div className="text-center">
              <h2 className="text-sm font-black text-slate-900 tracking-widest uppercase leading-none">
                {step === 'setup' ? 'Setup' : step === 'menu' ? 'Menu' : step === 'review' ? 'Review' : 'Payment'}
              </h2>
              <p className="text-[9px] font-bold text-blue-500 uppercase tracking-widest mt-1.5">{type}</p>
            </div>
            <div className="w-10"></div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto no-scrollbar">
        {step === 'setup' && (
           <div className="px-6 py-8 space-y-10">
              <section className="space-y-4">
                  <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Select Tables</h3>
                  <div className="grid grid-cols-4 gap-3">
                      {TABLES.map(t => (
                          <button
                              key={t}
                              onClick={() => toggleTable(t)}
                              className={`h-14 rounded-xl text-xs font-black border transition-all ${
                                  selectedTables.includes(t) ? 'bg-blue-500 border-blue-500 text-white' : 'bg-white border-slate-100 text-slate-400'
                              }`}
                          >
                              {t}
                          </button>
                      ))}
                  </div>
              </section>
              <button 
                disabled={selectedTables.length === 0}
                onClick={() => setStep('menu')}
                className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest disabled:opacity-30"
              >
                Continue
              </button>
           </div>
        )}

        {step === 'menu' && (
          <>
            <div className="px-6 pt-6 pb-2 sticky top-0 bg-[#FBFCFE] z-10">
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="Search items..." 
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full bg-white border border-slate-100 text-slate-700 py-3.5 pl-11 pr-4 rounded-2xl focus:outline-none focus:border-blue-500 shadow-sm text-sm font-bold transition-all"
                />
              </div>
            </div>
            <div className="px-6 py-4 space-y-4 pb-40">
              {filteredProducts.length > 0 ? (
                filteredProducts.map((product) => {
                  const qty = cart[product.id] || 0;
                  return (
                    <div key={product.id} className="bg-white rounded-[24px] p-4 border border-slate-100 flex gap-4">
                      <div className="w-20 h-20 rounded-[16px] overflow-hidden shrink-0 border border-slate-50">
                        <img src={product.image} className="w-full h-full object-cover" alt={product.name} />
                      </div>
                      <div className="flex-1 flex flex-col justify-between">
                        <div>
                          <h4 className="text-sm font-bold text-slate-900">{product.name}</h4>
                          <p className="text-[10px] text-slate-400 line-clamp-1">{product.description}</p>
                        </div>
                        <div className="flex justify-between items-center mt-2">
                          <span className="text-sm font-black">₹{product.price}</span>
                          {qty === 0 ? (
                            <button onClick={() => addToCart(product.id)} className="bg-blue-50 text-blue-600 px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest border border-blue-100">Add</button>
                          ) : (
                            <div className="flex items-center gap-3 bg-blue-500 text-white px-2 py-1 rounded-lg">
                              <button onClick={() => removeFromCart(product.id)}><Minus size={14} /></button>
                              <span className="text-xs font-bold">{qty}</span>
                              <button onClick={() => addToCart(product.id)}><Plus size={14} /></button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="py-20 text-center text-slate-400">
                  <p className="text-sm font-bold">No items found</p>
                </div>
              )}
            </div>
          </>
        )}

        {step === 'review' && (
          <div className="px-6 py-8 space-y-6">
            <div className="bg-white rounded-[32px] p-6 border border-slate-100 space-y-4">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Customer Details</h3>
              <input 
                placeholder="Name" 
                className={`w-full h-14 bg-slate-50 border rounded-2xl px-5 text-sm font-bold focus:outline-none ${nameError ? 'border-rose-500' : 'border-slate-100'}`} 
                value={customerName}
                onChange={e => setCustomerName(e.target.value)}
              />
              <input 
                placeholder="Phone" 
                type="tel"
                maxLength={10}
                className={`w-full h-14 bg-slate-50 border rounded-2xl px-5 text-sm font-bold focus:outline-none ${phoneError ? 'border-rose-500' : 'border-slate-100'}`} 
                value={customerPhone}
                onChange={e => setCustomerPhone(e.target.value.replace(/\D/g, ''))}
              />
            </div>
            <div className="bg-white rounded-[32px] p-6 border border-slate-100 space-y-4">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Summary</h3>
               {Object.entries(cart).map(([id, qty]) => {
                 const p = PRODUCTS.find(prod => prod.id === parseInt(id));
                 return (
                   <div key={id} className="flex justify-between text-sm">
                     <span className="font-bold text-slate-600">{qty}x {p?.name}</span>
                     <span className="font-black">₹{(p?.price || 0) * (qty as number)}</span>
                   </div>
                 );
               })}
               <div className="pt-4 border-t border-slate-50 flex justify-between">
                 <span className="text-sm font-black uppercase">Total</span>
                 <span className="text-xl font-black text-blue-500">₹{totalPrice.toFixed(0)}</span>
               </div>
            </div>
          </div>
        )}

        {step === 'payment' && (
           <div className="px-6 py-8 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setPaymentStatus('paid')}
                  className={`p-6 rounded-[32px] border text-center space-y-3 transition-all ${paymentStatus === 'paid' ? 'bg-blue-500 border-blue-500 text-white' : 'bg-white border-slate-100'}`}
                >
                  <CreditCard size={24} className="mx-auto" />
                  <p className="text-[10px] font-black uppercase tracking-widest">Mark Paid</p>
                </button>
                <button 
                  onClick={() => setPaymentStatus('unpaid')}
                  className={`p-6 rounded-[32px] border text-center space-y-3 transition-all ${paymentStatus === 'unpaid' ? 'bg-amber-500 border-amber-500 text-white' : 'bg-white border-slate-100'}`}
                >
                  <Banknote size={24} className="mx-auto" />
                  <p className="text-[10px] font-black uppercase tracking-widest">Pay Later</p>
                </button>
              </div>
              <button 
                disabled={!paymentStatus}
                onClick={handleCompleteOrder}
                className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest disabled:opacity-30"
              >
                Complete Order
              </button>
           </div>
        )}
      </div>

      {step === 'menu' && totalItems > 0 && (
        <div className="absolute bottom-0 inset-x-0 p-6 bg-white border-t border-slate-100">
           <button 
            onClick={() => setStep('review')}
            className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] flex items-center justify-between px-8 font-black uppercase tracking-widest"
           >
             <span>{totalItems} Items • Review</span>
             <span>₹{totalPrice.toFixed(0)}</span>
           </button>
        </div>
      )}

      {step === 'review' && (
        <div className="absolute bottom-0 inset-x-0 p-6 bg-white border-t border-slate-100">
           <button 
            onClick={handleReviewProceed}
            className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest"
           >
             Go to Payment
           </button>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Header } from './components/Header';
import { BottomNav } from './components/BottomNav';
import { Dashboard } from './components/Dashboard';
import { OrdersView } from './components/OrdersView';
import { EarningsView } from './components/EarningsView';
import { MenuView } from './components/MenuView';
import { ProfileView } from './components/ProfileView';
import { SubscriptionView } from './components/SubscriptionView';
import { SettingsView } from './components/SettingsView';
import { AdsMarketingView } from './components/AdsMarketingView';
import { OffersView } from './components/OffersView';
import { CreateOfferView } from './components/CreateOfferView';
import { StoreView } from './components/StoreView';
import { Sidebar } from './components/Sidebar';
import { QuickOrderView } from './components/QuickOrderView';
import { NotificationsView } from './components/NotificationsView';
import { LoginView } from './components/LoginView';
import { IntegrationsView } from './components/IntegrationsView';
import { TableView } from './components/TableView';
import { RefundsView } from './components/RefundsView';
import { AnalyticsView } from './components/AnalyticsView';
import { SalesReportView } from './components/SalesReportView';
import { Tab, Order } from './types';
import { HashRouter } from 'react-router-dom';

const BRANCHES = [
  { name: 'Gourmet Kitchen', location: 'Downtown Precinct', id: 'branch-1', status: 'Active' },
  { name: 'Gourmet Express', location: 'Business Bay', id: 'branch-2', status: 'Online' },
  { name: 'Gourmet Hub', location: 'Cyber City', id: 'branch-3', status: 'Active' }
];

const INITIAL_ORDERS: Order[] = [
  { id: 'ORD-011', time: '12:43', customer: 'Simran Kaur', items: '1 Item • Large Pepperoni Pizza', total: '899.00', channel: 'Crevings', status: 'Preparing', type: 'Delivery' },
  { id: 'ORD-012', time: '32:15', customer: 'Rahul Dravid', items: '2 Items • Veg Burger Meal', total: '450.00', channel: 'Zomato', status: 'Cooking', type: 'Delivery' },
  { id: 'ORD-014', time: '12:05', customer: 'Amit Patel', items: '3 Items • Family Feast', total: '1250.00', channel: 'Crevings', status: 'Ready', type: 'Delivery' },
  { id: 'ORD-015', time: '08:20', customer: 'Amit Sharma', total: '450.00', items: '2 Items • Veg Burger Meal', channel: 'Zomato', status: 'Cooking', type: 'Takeaway' },
  { id: 'ORD-022', time: '15:10', customer: 'Table 4', total: '1,250.00', items: '3 Items • Family Feast', channel: 'Internal', status: 'Ready', type: 'Dine-in' }
];

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(true);
  const [currentTab, setCurrentTab] = useState<Tab>(Tab.HOME);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isOnline, setIsOnline] = useState(true);
  const [rushHour, setRushHour] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [selectedBranch, setSelectedBranch] = useState(BRANCHES[0]);
  const [quickOrderType, setQuickOrderType] = useState<'Takeaway' | 'Dine-in' | null>(null);
  const [orders, setOrders] = useState<Order[]>(INITIAL_ORDERS);

  const handleAddOrder = (newOrder: Order) => {
    setOrders(prev => [newOrder, ...prev]);
  };

  const handleUpdateOrderStatus = (orderId: string) => {
    setOrders(prev => {
      const orderIndex = prev.findIndex(o => o.id === orderId);
      if (orderIndex === -1) return prev;

      const order = prev[orderIndex];
      let nextStatus = order.status;

      if (order.status === 'Incoming' || order.status === 'Accepted') nextStatus = 'Preparing';
      else if (order.status === 'Preparing' || order.status === 'Cooking') nextStatus = 'Ready';
      else if (order.status === 'Ready') nextStatus = 'Completed';

      if (nextStatus === 'Completed') {
        return prev.filter(o => o.id !== orderId);
      }

      const updatedOrders = [...prev];
      updatedOrders[orderIndex] = { ...order, status: nextStatus };
      return updatedOrders;
    });
  };

  const renderContent = () => {
    switch (currentTab) {
      case Tab.HOME:
        return (
          <Dashboard 
            orders={orders}
            onAddOrder={handleAddOrder}
            onUpdateOrderStatus={handleUpdateOrderStatus}
            onNavigateToOrders={() => setCurrentTab(Tab.ORDERS)} 
            onNavigateToTables={() => setCurrentTab(Tab.TABLES)}
            onQuickOrder={(type) => setQuickOrderType(type)}
            isOnline={isOnline}
            setIsOnline={setIsOnline}
            rushHour={rushHour}
            setRushHour={setRushHour}
            selectedBranch={selectedBranch}
          />
        );
      case Tab.ORDERS:
        return <OrdersView orders={orders} onUpdateOrderStatus={handleUpdateOrderStatus} />;
      case Tab.EARNINGS:
        return <EarningsView />;
      case Tab.ANALYTICS:
        return <AnalyticsView />;
      case Tab.MENU:
        return <MenuView />;
      case Tab.PROFILE:
        return <ProfileView 
          onNavigateToTab={(tab) => setCurrentTab(tab)} 
          onLogout={() => setIsLoggedIn(false)}
        />;
      case Tab.SUBSCRIPTION:
        return <SubscriptionView onBack={() => setCurrentTab(Tab.PROFILE)} />;
      case Tab.SETTINGS:
        return <SettingsView />;
      case Tab.ADS_MARKETING:
        return <AdsMarketingView />;
      case Tab.OFFERS:
        return <OffersView />;
      case Tab.CREATE_OFFER:
        return <CreateOfferView />;
      case Tab.OUTLET:
        return <StoreView />;
      case Tab.TABLES:
        return <TableView />;
      case Tab.REFUNDS:
        return <RefundsView />;
      case Tab.NOTIFICATIONS:
        return <NotificationsView onBack={() => setCurrentTab(Tab.HOME)} />;
      case Tab.INTEGRATIONS:
        return <IntegrationsView onBack={() => setCurrentTab(Tab.PROFILE)} />;
      case Tab.SALES_REPORT:
        return <SalesReportView />;
      case Tab.CUSTOMER_DATA:
        return (
          <div className="flex flex-col items-center justify-center h-[70vh] text-slate-400 animate-in fade-in">
            <h2 className="text-xl font-bold text-slate-900 mb-2">Customer Data</h2>
            <p>Database of loyal customers and dining habits.</p>
          </div>
        );
      default:
        return (
          <div className="flex flex-col items-center justify-center h-[70vh] text-slate-400 animate-in fade-in">
            <p>Coming Soon</p>
          </div>
        );
    }
  };

  if (!isLoggedIn) {
    return <LoginView onLogin={() => setIsLoggedIn(true)} />;
  }

  return (
    <HashRouter>
      <div className="min-h-screen bg-white relative z-10 overflow-x-hidden">
        <div className="bg-white min-h-screen">
          <Header 
            onMenuClick={() => setIsSidebarOpen(true)} 
            onNotificationClick={() => setCurrentTab(Tab.NOTIFICATIONS)}
            isOnline={isOnline}
            onToggleOnline={() => setIsOnline(!isOnline)}
            rushHour={rushHour}
            onToggleRush={() => setRushHour(!rushHour)}
            isPaused={isPaused}
            onTogglePause={() => setIsPaused(!isPaused)}
          />

          <Sidebar 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
            currentTab={currentTab}
            onTabChange={setCurrentTab}
            branches={BRANCHES}
            selectedBranch={selectedBranch}
            onBranchChange={setSelectedBranch}
          />

          <main className="max-w-md mx-auto w-full relative">
            <div className="transition-opacity duration-300">
              {renderContent()}
            </div>
          </main>
        </div>

        <BottomNav currentTab={currentTab} onTabChange={setCurrentTab} />

        {/* Quick Order Overlay */}
        {quickOrderType && (
            <QuickOrderView 
                type={quickOrderType} 
                onBack={() => setQuickOrderType(null)} 
            />
        )}
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        body {
          background-color: #FFFFFF;
          -webkit-tap-highlight-color: transparent;
        }
        main {
          -webkit-overflow-scrolling: touch;
        }
      `}} />
    </HashRouter>
  );
};

export default App;

