              <Pause size={12} strokeWidth={3} fill={isPaused ? 'white' : 'none'} />
            </div>
          </button>

          {/* Rush Hour Toggle */}
          <button
            onClick={onToggleRush}
            style={{ 
              backgroundColor: rushHour ? 'rgba(255,0,0,0.05)' : '#F8FAFC',
              borderColor: rushHour ? 'rgba(255,0,0,0.2)' : '#E2E8F0'
            }}
            className="flex items-center gap-1.5 pl-1.5 pr-2.5 py-1.5 rounded-xl border transition-all duration-300 active:scale-95"
          >
            <div 
              style={{ backgroundColor: rushHour ? pureRed : '#94A3B8' }}
              className="w-6 h-6 rounded-lg flex items-center justify-center text-white"
            >
              <Zap size={12} strokeWidth={3} fill={rushHour ? 'white' : 'none'} />
            </div>
            <span 
              style={{ color: rushHour ? pureRed : '#64748B' }}
              className="text-[10px] font-black uppercase tracking-wider leading-none"
            >
              Rush
            </span>
          </button>

          {/* Online/Offline Toggle Button */}
          <button
            onClick={onToggleOnline}
            style={{ 
              backgroundColor: isOnline ? 'rgba(0,127,255,0.05)' : '#F8FAFC',
              borderColor: isOnline ? 'rgba(0,127,255,0.2)' : '#E2E8F0'
            }}
            className="flex items-center gap-1.5 pl-1.5 pr-3 py-1.5 rounded-xl border transition-all duration-300 active:scale-95"
          >
            <div 
              style={{ backgroundColor: isOnline ? blueColor : '#94A3B8' }}
              className="w-6 h-6 rounded-lg flex items-center justify-center text-white"
            >
              <Power size={12} strokeWidth={3} />
            </div>
            <span 
              style={{ color: isOnline ? blueColor : '#64748B' }}
              className="text-[10px] font-black uppercase tracking-wider leading-none"
            >
              {isOnline ? 'Online' : 'Offline'}
            </span>
          </button>

        </div>

      </div>
    </header>
  );
};

