              </div>
            </div>
            <div className="px-4 py-4 grid grid-cols-2 gap-x-4 gap-y-8 pb-40">
              {filteredProducts.length > 0 ? (
                filteredProducts.map((product) => {
                  const qty = cart[product.id] || 0;
                  return (
                    <div key={product.id} className="flex flex-col animate-in fade-in duration-500">
                      {/* Product Image Container */}
                      <div className="relative aspect-square w-full rounded-[28px] overflow-hidden bg-slate-100 mb-3 shadow-sm border border-slate-50">
                        <img 
                          src={product.image} 
                          className="w-full h-full object-cover transition-transform duration-500 hover:scale-105" 
                          alt={product.name} 
                        />
                      </div>

                      {/* Header row: Veg/Non-veg icon & Rating */}
                      <div className="flex items-center justify-between mb-1.5 px-1">
                        <div className="flex items-center gap-1.5">
                          <div className={`w-4 h-4 rounded-sm border flex items-center justify-center shrink-0 ${product.isVeg ? 'border-emerald-500' : 'border-rose-500'}`}>
                            <div className={`w-1.5 h-1.5 rounded-full ${product.isVeg ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
                          </div>
                          {product.isBestseller && (
                            <div className="flex items-center gap-0.5 text-[#F04438] text-[10px] font-bold">
                              <Star size={10} fill="currentColor" />
                              <span>Bestseller</span>
                            </div>
                          )}
                        </div>
                        <div className="bg-[#F0FDF9] text-[#10B981] px-1.5 py-0.5 rounded-md flex items-center gap-0.5 border border-[#10B981]/10">
                          <Star size={10} fill="currentColor" />
                          <span className="text-[10px] font-black">{product.rating}</span>
                          <span className="text-[9px] font-bold opacity-60">({product.reviewCount})</span>
                        </div>
                      </div>

                      {/* Title & Code */}
                      <div className="mb-3 px-1">
                        <h4 className="text-[15px] font-black text-slate-900 leading-tight tracking-tight line-clamp-2">
                          {product.name}
                        </h4>
                        <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest mt-1">Code: {product.code}</p>
                      </div>

                      {/* Footer: Prices & Add Button */}
                      <div className="mt-auto flex items-center justify-between px-1">
                        <div className="flex flex-col">
                          <span className="text-[11px] font-bold text-slate-300 line-through leading-none">₹{product.originalPrice}</span>
                          <span className="text-[17px] font-black text-slate-900 leading-none mt-1">₹{product.price}</span>
                        </div>

                        {qty === 0 ? (
                          <button 
                            onClick={() => addToCart(product.id)} 
                            className="bg-white text-[#10B981] border border-[#10B981] px-5 py-2 rounded-xl text-[12px] font-black uppercase tracking-widest active:scale-95 transition-all hover:bg-emerald-50"
                          >
                            Add
                          </button>
                        ) : (
                          <div className="flex items-center gap-3 bg-[#10B981] text-white px-2 py-1.5 rounded-xl">
                            <button onClick={() => removeFromCart(product.id)} className="p-0.5 active:scale-75"><Minus size={14} /></button>
                            <span className="text-xs font-black">{qty}</span>
                            <button onClick={() => addToCart(product.id)} className="p-0.5 active:scale-75"><Plus size={14} /></button>
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })
              ) : (
                <div className="col-span-2 py-20 text-center text-slate-400">
                  <p className="text-sm font-bold">No items found</p>
                </div>
              )}
            </div>
          </>
        )}

        {step === 'review' && (
          <div className="px-6 py-8 space-y-6">
            <div className="bg-white rounded-[32px] p-6 border border-slate-100 space-y-4">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Customer Details</h3>
              <input 
                placeholder="Name" 
                className={`w-full h-14 bg-slate-50 border rounded-2xl px-5 text-sm font-bold focus:outline-none ${nameError ? 'border-rose-500' : 'border-slate-100'}`} 
                value={customerName}
                onChange={e => setCustomerName(e.target.value)}
              />
              <input 
                placeholder="Phone" 
                type="tel"
                maxLength={10}
                className={`w-full h-14 bg-slate-50 border rounded-2xl px-5 text-sm font-bold focus:outline-none ${phoneError ? 'border-rose-500' : 'border-slate-100'}`} 
                value={customerPhone}
                onChange={e => setCustomerPhone(e.target.value.replace(/\D/g, ''))}
              />
            </div>
            <div className="bg-white rounded-[32px] p-6 border border-slate-100 space-y-4">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Summary</h3>
               {Object.entries(cart).map(([id, qty]) => {
                 const p = PRODUCTS.find(prod => prod.id === parseInt(id));
                 return (
                   <div key={id} className="flex justify-between text-sm">
                     <span className="font-bold text-slate-600">{qty}x {p?.name}</span>
                     <span className="font-black">₹{(p?.price || 0) * (qty as number)}</span>
                   </div>
                 );
               })}
               <div className="pt-4 border-t border-slate-50 flex justify-between">
                 <span className="text-sm font-black uppercase">Total</span>
                 <span className="text-xl font-black text-blue-500">₹{totalPrice.toFixed(0)}</span>
               </div>
            </div>
          </div>
        )}

        {step === 'payment' && (
           <div className="px-6 py-8 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setPaymentStatus('paid')}
                  className={`p-6 rounded-[32px] border text-center space-y-3 transition-all ${paymentStatus === 'paid' ? 'bg-blue-500 border-blue-500 text-white' : 'bg-white border-slate-100'}`}
                >
                  <CreditCard size={24} className="mx-auto" />
                  <p className="text-[10px] font-black uppercase tracking-widest">Mark Paid</p>
                </button>
                <button 
                  onClick={() => setPaymentStatus('unpaid')}
                  className={`p-6 rounded-[32px] border text-center space-y-3 transition-all ${paymentStatus === 'unpaid' ? 'bg-amber-500 border-amber-500 text-white' : 'bg-white border-slate-100'}`}
                >
                  <Banknote size={24} className="mx-auto" />
                  <p className="text-[10px] font-black uppercase tracking-widest">Pay Later</p>
                </button>
              </div>
              <button 
                disabled={!paymentStatus}
                onClick={handleCompleteOrder}
                className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest disabled:opacity-30"
              >
                Complete Order
              </button>
           </div>
        )}
      </div>

      {step === 'menu' && totalItems > 0 && (
        <div className="px-6 pb-6 bg-white border-t border-slate-100">
           <button 
            onClick={() => setStep('review')}
            className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] flex items-center justify-between px-8 font-black uppercase tracking-widest"
           >
             <span>{totalItems} Items • Review</span>
             <span>₹{totalPrice.toFixed(0)}</span>
           </button>
        </div>
      )}

      {step === 'review' && (
        <div className="px-6 pb-6 bg-white border-t border-slate-100">
           <button 
            onClick={handleReviewProceed}
            className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest"
           >
             Go to Payment
           </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
