                       <div className="flex-1 h-px bg-slate-100"></div>
                       <span className="text-[10px] font-bold text-slate-300">{groupedProducts[catName].length} Items</span>
                    </div>

                    <div className="grid grid-cols-2 gap-x-4 gap-y-10">
                      {groupedProducts[catName].map((product) => {
                        const qty = cart[product.id] || 0;
                        return (
                          <div key={product.id} className="flex flex-col animate-in fade-in duration-500">
                            {/* Product Image Container */}
                            <div className="relative aspect-square w-full rounded-[28px] overflow-hidden bg-slate-100 mb-3 shadow-sm border border-slate-50">
                              <img 
                                src={product.image} 
                                className="w-full h-full object-cover transition-transform duration-500 hover:scale-105" 
                                alt={product.name} 
                              />
                            </div>

                            {/* Header row: Veg/Non-veg icon & Rating */}
                            <div className="flex items-center justify-between mb-1.5 px-1">
                              <div className="flex items-center gap-1.5">
                                <div className={`w-4 h-4 rounded-sm border flex items-center justify-center shrink-0 ${product.isVeg ? 'border-emerald-500' : 'border-rose-500'}`}>
                                  <div className={`w-1.5 h-1.5 rounded-full ${product.isVeg ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>
                                </div>
                                {product.isBestseller && (
                                  <div className="flex items-center gap-0.5 text-[#F04438] text-[9px] font-bold uppercase tracking-tight">
                                    <Star size={9} fill="currentColor" />
                                    <span>Bestseller</span>
                                  </div>
                                )}
                              </div>
                              <div className="bg-[#F0FDF9] text-[#10B981] px-1.5 py-0.5 rounded-md flex items-center gap-0.5 border border-[#10B981]/10">
                                <Star size={9} fill="currentColor" />
                                <span className="text-[9px] font-black">{product.rating}</span>
                              </div>
                            </div>

                            {/* Title & Code */}
                            <div className="mb-3 px-1">
                              <h4 className="text-[14px] font-black text-slate-900 leading-tight tracking-tight line-clamp-2 min-h-[2.5em]">
                                {product.name}
                              </h4>
                              <p className="text-[9px] font-black text-blue-500 uppercase tracking-widest mt-1">Code: {product.code}</p>
                            </div>

                            {/* Footer: Prices & Add Button */}
                            <div className="mt-auto flex items-center justify-between px-1">
                              <div className="flex flex-col">
                                <span className="text-[10px] font-bold text-slate-300 line-through leading-none">₹{product.originalPrice}</span>
                                <span className="text-[16px] font-black text-slate-900 leading-none mt-1">₹{product.price}</span>
                              </div>

                              {qty === 0 ? (
                                <button 
                                  onClick={() => addToCart(product.id)} 
                                  className="bg-white text-[#10B981] border border-[#10B981] px-5 py-2 rounded-xl text-[11px] font-black uppercase tracking-widest active:scale-95 transition-all hover:bg-emerald-50"
                                >
                                  Add
                                </button>
                              ) : (
                                <div className="flex items-center gap-3 bg-[#10B981] text-white px-2 py-1.5 rounded-xl">
                                  <button onClick={() => removeFromCart(product.id)} className="p-0.5 active:scale-75"><Minus size={13} /></button>
                                  <span className="text-xs font-black">{qty}</span>
                                  <button onClick={() => addToCart(product.id)} className="p-0.5 active:scale-75"><Plus size={13} /></button>
                                </div>
                              )}
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))
              ) : (
                <div className="col-span-2 py-20 text-center text-slate-400">
                  <p className="text-sm font-bold">No items found</p>
