                         </button>
                         <span className="text-xl font-black text-slate-900 w-6 text-center">{guestCount}</span>
                         <button 
                           onClick={() => setGuestCount(guestCount + 1)}
                           className="w-10 h-10 rounded-xl bg-white border border-slate-100 flex items-center justify-center text-slate-400 active:scale-90 transition-all"
                         >
                            <Plus size={16} />
                         </button>
                      </div>
                   </div>

                   {/* Table Selection */}
                   <div className="space-y-3">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Assign Tables</p>
                      <div className="grid grid-cols-4 gap-2">
                        {TABLES.map(t => (
