                <button 
                  onClick={() => setPaymentStatus('unpaid')}
                  className={`p-6 rounded-[32px] border text-center space-y-3 transition-all ${paymentStatus === 'unpaid' ? 'bg-amber-500 border-amber-500 text-white' : 'bg-white border-slate-100'}`}
                >
                  <Banknote size={24} className="mx-auto" />
                  <p className="text-[10px] font-black uppercase tracking-widest">Pay Later</p>
                </button>
              </div>
              <button 
                disabled={!paymentStatus}
                onClick={handleCompleteOrder}
                className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest disabled:opacity-30"
              >
                Complete Order
              </button>
           </div>
        )}
      </div>

      {step === 'menu' && totalItems > 0 && (
        <div className="fixed bottom-0 inset-x-0 p-6 bg-white/80 backdrop-blur-xl border-t border-slate-100 shadow-[0_-15px_40px_rgba(0,0,0,0.06)] animate-in slide-in-from-bottom duration-500 z-40">
           <button 
            onClick={() => setStep('review')}
            className="w-full h-[72px] bg-[#007FFF] text-white rounded-[28px] flex items-center justify-between pl-2 pr-6 font-black active:scale-[0.98] transition-all shadow-2xl shadow-blue-500/30 group relative overflow-hidden"
           >
             {/* Glossy Overlay */}
             <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent opacity-50 group-hover:scale-110 transition-transform duration-700"></div>

             <div className="flex items-center gap-4 relative z-10">
               <div className="bg-white/15 w-14 h-14 rounded-[22px] flex items-center justify-center relative backdrop-blur-md border border-white/10 group-hover:bg-white/25 transition-colors">
                 <ShoppingBag size={24} strokeWidth={2.5} />
                 <span className="absolute -top-1.5 -right-1.5 w-6 h-6 bg-rose-500 rounded-full flex items-center justify-center text-[11px] font-black border-2 border-[#007FFF] shadow-md animate-in zoom-in duration-300">
                    {totalItems}
                 </span>
               </div>
               <div className="text-left">
                 <p className="text-[14px] uppercase tracking-[0.1em] leading-none">View Review</p>
                 <p className="text-[10px] font-bold text-white/60 uppercase tracking-[0.05em] mt-1.5">{totalItems} items added</p>
               </div>
             </div>

             <div className="flex items-center gap-4 relative z-10">
               <div className="h-10 w-[1px] bg-white/15"></div>
               <div className="text-right">
                 <p className="text-[11px] font-bold text-white/50 uppercase tracking-widest leading-none mb-1.5">Total</p>
                 <div className="flex items-center gap-2">
                    <span className="text-[20px] tracking-tighter">₹{totalPrice.toFixed(0)}</span>
                    <ChevronRight size={20} strokeWidth={3} className="text-white/40 group-hover:translate-x-1 transition-transform" />
                 </div>
               </div>
             </div>
           </button>
        </div>
      )}

      {step === 'review' && (
        <div className="px-6 pb-10 bg-white border-t border-slate-100 mt-auto">
           <button 
            onClick={handleReviewProceed}
            className="w-full h-16 bg-[#007FFF] text-white rounded-[24px] font-black uppercase tracking-widest mt-4 shadow-xl shadow-blue-500/20"
           >
             Go to Payment
           </button>
        </div>
      )}
    </div>
  );
};

