                <div className="relative group">
                  <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" size={18} />
                  <input 
                    type="text" 
                    placeholder="Search dishes, drinks or codes..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full h-14 bg-white border-2 border-slate-100 text-slate-700 pl-12 pr-6 rounded-[22px] focus:outline-none focus:border-blue-500 focus:bg-white shadow-sm hover:border-slate-200 text-[15px] font-bold transition-all placeholder:text-slate-300"
                  />
                </div>
              </div>
              {/* Category Scroll */}
              <div className="flex gap-2 overflow-x-auto no-scrollbar px-6 pb-4">
                 {CATEGORIES.map(cat => (
                   <button 
                     key={cat}
                     onClick={() => setActiveCategory(cat)}
                     className={`flex-shrink-0 px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all duration-300 border ${
                       activeCategory === cat 
                         ? 'bg-slate-900 border-slate-900 text-white shadow-lg' 
                         : 'bg-white border-slate-100 text-slate-400'
                     }`}
                   >
                     {cat}
                   </button>
                 ))}
              </div>
            </div>

            <div className="px-4 py-6 space-y-12 pb-44">
              {sortedCategories.length > 0 ? (
                sortedCategories.map((catName) => (
                  <div key={catName} className="space-y-6">
                    <div className="flex items-center gap-3 px-2">
                       <div className="h-5 w-1 rounded-full bg-blue-500"></div>
                       <h3 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em]">{catName}</h3>
                       <div className="flex-1 h-px bg-slate-100"></div>
                       <span className="text-[10px] font-bold text-slate-300">{groupedProducts[catName].length} Items</span>
                    </div>

                    <div className="grid grid-cols-2 gap-x-4 gap-y-10">
                      {groupedProducts[catName].map((product) => {
