              <div className="grid grid-cols-1 gap-4">
                <div className="relative group">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-blue-500 transition-colors" size={16} />
                  <input 
                    placeholder="Phone Number" 
                    type="tel"
                    maxLength={10}
                    className={`w-full h-14 bg-slate-50/50 border rounded-2xl pl-11 pr-5 text-sm font-bold focus:outline-none focus:bg-white focus:border-blue-500 transition-all ${phoneError ? 'border-rose-500' : 'border-slate-100'}`} 
                    value={customerPhone}
                    onChange={e => setCustomerPhone(e.target.value.replace(/\D/g, ''))}
                  />
                  {isSavedCustomer && (
                    <div className="absolute right-4 top-1/2 -translate-y-1/2">
                      <CheckCircle2 size={18} className="text-emerald-500" strokeWidth={3} />
                    </div>
                  )}
                </div>

                <div className="relative group">
                  <UserIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-blue-500 transition-colors" size={16} />
                  <input 
                    placeholder="Name" 
                    className={`w-full h-14 bg-slate-50/50 border rounded-2xl pl-11 pr-5 text-sm font-bold focus:outline-none focus:bg-white focus:border-blue-500 transition-all ${nameError ? 'border-rose-500' : 'border-slate-100'}`} 
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                </div>

                <div className="relative group">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-blue-500 transition-colors" size={16} />
                  <input 
                    placeholder="Email Address" 
                    type="email"
                    className="w-full h-14 bg-slate-50/50 border border-slate-100 rounded-2xl pl-11 pr-5 text-sm font-bold focus:outline-none focus:bg-white focus:border-blue-500 transition-all" 
                    value={customerEmail}
                    onChange={e => setCustomerEmail(e.target.value)}
                  />
                </div>

                <div className="space-y-2">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Gender</p>
                  <div className="flex gap-2">
                    {(['Male', 'Female', 'Other'] as const).map(g => (
                      <button 
                        key={g}
                        onClick={() => setCustomerGender(g)}
                        className={`flex-1 h-12 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${
                          customerGender === g 
                            ? 'bg-slate-900 border-slate-900 text-white shadow-md' 
                            : 'bg-white border-slate-100 text-slate-400 hover:bg-slate-50'
                        }`}
                      >
                        {g}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {isSavedCustomer && (
                <div className="pt-4 border-t border-slate-50 animate-in fade-in slide-in-from-top-2 duration-500">
                  <button 
                    onClick={() => setShowHistory(!showHistory)}
                    className="w-full flex items-center justify-between p-4 bg-blue-50/50 rounded-2xl border border-blue-100/50 group active:scale-[0.98] transition-all"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-xl bg-white border border-blue-100 flex items-center justify-center text-blue-500">
                        <History size={18} />
